function getMonthlyTargetFromSheet(nameKm) {
  const d = (typeof DataService !== 'undefined' && DataService.data) ? DataService.data : null;
  if (!d || !d.monthlyTargets) return 0;
  const cleanName = nameKm.replace('លោក ', '').replace('អ្នកគ្រូ ', '').trim();
  const norm = (typeof normalizeSellerName === 'function') ? normalizeSellerName(nameKm) : cleanName.toLowerCase();
  if (d.monthlyTargets[nameKm]) return Number(d.monthlyTargets[nameKm]);
  if (d.monthlyTargets[cleanName]) return Number(d.monthlyTargets[cleanName]);
  if (d.monthlyTargets[norm]) return Number(d.monthlyTargets[norm]);
  for (const [k, v] of Object.entries(d.monthlyTargets)) {
    const kClean = k.replace('លោក ', '').replace('អ្នកគ្រូ ', '').trim();
    const kNorm = (typeof normalizeSellerName === 'function') ? normalizeSellerName(k) : kClean.toLowerCase();
    if (kClean === cleanName || kNorm === norm || (cleanName && kClean.includes(cleanName)) || (cleanName && cleanName.includes(kClean))) {
      return Number(v);
    }
  }
  return 0;
}

function getManagerTarget(mgrKm) {
  const t = getMonthlyTargetFromSheet(mgrKm);
  return t > 0 ? t : 100;
}

function getLeaderTarget(ldrKm) {
  const t = getMonthlyTargetFromSheet(ldrKm);
  return t > 0 ? t : 0;
}

function setManagerTarget(mgrKm, targetVal) {
  try {
    localStorage.setItem(`sd_mgr_target_${mgrKm}`, targetVal);
  } catch (_) {}
}

function isDirectorOrAdminUser() {
  const isMaster = (window.DataService && typeof window.DataService.isMasterSheet === 'function' && window.DataService.isMasterSheet());
  if (isMaster) return true;

  if (typeof getExecMaxRole === 'function' && getExecMaxRole() === 'director') return true;

  const p = (typeof getProfileData === 'function') ? getProfileData() : null;
  const candidates = [
    p && p.name,
    p && p.subtitle,
    localStorage.getItem('sd_last_seller')
  ].filter(Boolean);

  for (const cand of candidates) {
    const lower = cand.toLowerCase().trim();
    const norm = (typeof normalizeSellerName === 'function') ? normalizeSellerName(cand) : lower;

    // Director Bech Nora check
    if (lower.includes('nora') || lower.includes('bech') || norm.includes('នោរ៉ា') || norm.includes('ប៊ិច')) {
      return true;
    }
    // Creator / Admin Sdey Sdoeung check
    if (lower.includes('sdey') || lower.includes('sdoeung') || cand.includes('ស្ដី') || cand.includes('ស្តី')) {
      return true;
    }
  }
  return false;
}

function canViewAndEditManagerTarget(managerOrKm) {
  if (!managerOrKm) return false;

  // 1. Director or Creator/Admin can view and edit targets for ALL managers!
  if (isDirectorOrAdminUser()) return true;

  // 2. Otherwise, only the Manager whose Profile matches this card can view and edit!
  const p = (typeof getProfileData === 'function') ? getProfileData() : null;
  const currentName = (p && p.name) ? p.name.trim() : '';
  const currentSub = (p && p.subtitle) ? p.subtitle.trim() : '';
  const lastSeller = (localStorage.getItem('sd_last_seller') || '').trim();

  let mgrKm = '';
  let mgrEn = '';

  if (typeof managerOrKm === 'string') {
    mgrKm = managerOrKm.trim();
    const found = (typeof findBostarSeller === 'function') ? findBostarSeller(mgrKm) : null;
    if (found) mgrEn = found.en || '';
  } else if (typeof managerOrKm === 'object') {
    mgrKm = (managerOrKm.km || '').trim();
    mgrEn = (managerOrKm.en || '').trim();
  }

  const normKm = (typeof normalizeSellerName === 'function') ? normalizeSellerName(mgrKm) : mgrKm.toLowerCase().trim();
  const normEn = mgrEn ? mgrEn.toLowerCase().trim() : '';

  const candidates = [currentName, currentSub, lastSeller].filter(Boolean);

  for (const cand of candidates) {
    const normCand = (typeof normalizeSellerName === 'function') ? normalizeSellerName(cand) : cand.toLowerCase().trim();
    const candLower = cand.toLowerCase().trim();

    // 1. Match Khmer name (direct or normalized or contains)
    if (normKm && (normKm === normCand || normKm.includes(normCand) || normCand.includes(normKm))) {
      return true;
    }
    // 2. Match Latin name (case-insensitive)
    if (normEn && (normEn === candLower || normEn.includes(candLower) || candLower.includes(normEn))) {
      return true;
    }
    // 3. Substring match
    if (mgrKm && (mgrKm.includes(cand) || cand.includes(mgrKm))) {
      return true;
    }
  }

  return false;
}

const canEditManagerTarget = canViewAndEditManagerTarget;

function editManagerTargetPrompt(mgrKm, event) {
  if (event) event.stopPropagation();
  if (!canViewAndEditManagerTarget(mgrKm)) {
    if (typeof showToastNotification === 'function') {
      showToastNotification('🔒 អ្នកអាចកំណត់គោលដៅបានតែសម្រាប់ Profile របស់ខ្លួនឯងប៉ុណ្ណោះ!');
    }
    if (navigator.vibrate) try { navigator.vibrate([30, 50, 30]); } catch (_) {}
    return;
  }
  const currentTarget = getManagerTarget(mgrKm);
  const cleanName = mgrKm.replace('លោក ', '').replace('អ្នកគ្រូ ', '');
  const newVal = prompt(`កំណត់គោលដៅលក់សម្រាប់ក្រុម ${cleanName} (ចំនួនប្រអប់)៖`, currentTarget);
  if (newVal !== null) {
    const num = parseInt(newVal, 10);
    if (!isNaN(num) && num > 0) {
      setManagerTarget(mgrKm, num);
      if (typeof showToastNotification === 'function') {
        showToastNotification(`បានកំណត់គោលដៅក្រុម ${cleanName} ៖ ${num} ប្រអប់ 🎯`);
      }
      renderExecutiveHierarchyModalContent();
      renderCurrentView();
    }
  }
}

function getManagerRankBadge(rank) {
  if (rank === 1) {
    return `<span class="w-6 h-6 rounded-full bg-amber-500/20 border border-amber-400/50 text-amber-300 font-bold text-xs flex items-center justify-center shrink-0 shadow-sm shadow-amber-500/20">🥇</span>`;
  } else if (rank === 2) {
    return `<span class="w-6 h-6 rounded-full bg-slate-300/20 border border-slate-300/40 text-slate-200 font-bold text-xs flex items-center justify-center shrink-0">🥈</span>`;
  } else if (rank === 3) {
    return `<span class="w-6 h-6 rounded-full bg-amber-700/20 border border-amber-700/40 text-amber-400 font-bold text-xs flex items-center justify-center shrink-0">🥉</span>`;
  } else if (rank === 4) {
    return `<span class="w-6 h-6 rounded-full bg-amber-500/15 border-2 border-amber-400/80 text-amber-300 font-bold font-mono text-xs flex items-center justify-center shrink-0 shadow-sm shadow-amber-500/20">4</span>`;
  } else if (rank === 5) {
    return `<span class="w-6 h-6 rounded-full bg-emerald-500/15 border-2 border-emerald-400/80 text-emerald-300 font-bold font-mono text-xs flex items-center justify-center shrink-0 shadow-sm shadow-emerald-500/20">5</span>`;
  } else {
    return `<span class="w-6 h-6 rounded-full bg-sky-500/15 border-2 border-sky-400/80 text-sky-300 font-bold font-mono text-xs flex items-center justify-center shrink-0 shadow-sm shadow-sky-500/20">${rank}</span>`;
  }
}

window.navOpenedFromDrawer = {
  customers: false,
  attendance: false,
  dailyReport: false,
  teamMembers: false,
  expenses: false,
  honors: false,
  editProfile: false,
  profileSubModal: false,
  tutorial: false,
  execHierarchy: false
};

function openExecutiveHierarchyFromDrawer() {
  window.execHierarchyOpenedFromDrawer = true;
  if (window.navOpenedFromDrawer) window.navOpenedFromDrawer.execHierarchy = true;
  const isUnlocked = (sessionStorage.getItem('sd_exec_unlocked') === 'true');
  if (isUnlocked) {
    if (typeof closeProfileDrawer === 'function') closeProfileDrawer();
    openExecutiveHierarchyModal();
  } else {
    openExecutivePasscodeModal('drawer');
  }
}

function openExecutiveHierarchyModal() {
  const modal = document.getElementById('executive-hierarchy-modal');
  if (!modal) return;
  modal.classList.remove('hidden');

  // ALWAYS default to current month ("ខែ") upon entering modal:
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  execHierarchyFilterState.mode = 'month';
  execHierarchyFilterState.selectedMonth = `${y}-${m}`;
  execHierarchyFilterState.selectedYear = String(y);
  execHierarchyFilterState.calYear = y;
  execHierarchyFilterState.calMonth = now.getMonth() + 1;

  renderExecutiveHierarchyDateFilterBar();
  renderExecutiveRoleSwitcherHtml('modal');
  renderExecutiveHierarchyModalContent();
  setupExecutiveHierarchyScroll();
  setDockVisible(false);

  if (window.lucide) window.lucide.createIcons();
  if (navigator.vibrate) try { navigator.vibrate(12); } catch (_) {}
}

function closeExecutiveHierarchyModal() {
  closeAllExecDropdowns();
  const modal = document.getElementById('executive-hierarchy-modal');
  if (modal) modal.classList.add('hidden');

  if (window.execHierarchyOpenedFromDrawer) {
    window.execHierarchyOpenedFromDrawer = false;
    if (typeof openProfileDrawer === 'function') {
      openProfileDrawer(false);
    }
  } else {
    if (!isDialogModalOpen()) {
      setDockVisible(true);
    }
  }
}

function relockExecutiveHierarchyModal() {
  sessionStorage.removeItem('sd_exec_unlocked');
  sessionStorage.removeItem('sd_exec_role');
  execHierarchyFilterState.selectedManager = null;
  execHierarchyFilterState.selectedLeader = null;
  closeExecutiveHierarchyModal();
  renderCurrentView();
  if (navigator.vibrate) try { navigator.vibrate(12); } catch (_) {}
  if (typeof showToastNotification === 'function') {
    showToastNotification('បានចាក់សោរកាតរចនាសម្ព័ន្ធលក់វិញជោគជ័យ! 🔒');
  }
}

function setupExecutiveHierarchyScroll() {
  const scrollEl = document.getElementById('executive-hierarchy-scroll-body');
  const filterBar = document.getElementById('exec-modal-date-filter-bar');
  if (!scrollEl || execHierarchyScrollInitialized) return;
  execHierarchyScrollInitialized = true;

  let lastScrollTop = scrollEl.scrollTop || 0;
  scrollEl.addEventListener('scroll', () => {
    closeAllExecDropdowns();
    const currentScrollTop = scrollEl.scrollTop;
    const diff = currentScrollTop - lastScrollTop;

    if (diff > 8 && currentScrollTop > 40) {
      if (filterBar) {
        filterBar.style.maxHeight = '0px';
        filterBar.style.opacity = '0';
        filterBar.style.transform = 'translateY(-8px)';
        filterBar.style.pointerEvents = 'none';
      }
    } else if (diff < -8 || currentScrollTop <= 10) {
      if (filterBar) {
        filterBar.style.maxHeight = '80px';
        filterBar.style.opacity = '1';
        filterBar.style.transform = 'translateY(0)';
        filterBar.style.pointerEvents = 'auto';
      }
    }
    lastScrollTop = currentScrollTop;
  }, { passive: true });
}

function renderExecutiveHierarchyDateFilterBar() {
  const container = document.getElementById('exec-modal-date-filter-bar');
  if (!container) return;

  const mode = execHierarchyFilterState.mode || 'all';
  const now = new Date();
  const currentIsoDay = getLocalIsoDate(now);
  const currentIsoMonth = currentIsoDay.slice(0, 7);
  const currentIsoYear = currentIsoDay.slice(0, 4);

  let dayLabel = 'ថ្ងៃទី';
  if (mode === 'day') {
    const selectedDay = execHierarchyFilterState.selectedDate || currentIsoDay;
    if (selectedDay === currentIsoDay) {
      dayLabel = 'ថ្ងៃនេះ';
    } else if (selectedDay === getYesterdayIso()) {
      dayLabel = 'ម្សិលមិញ';
    } else {
      const parts = selectedDay.split('-');
      dayLabel = `ថ្ងៃទី ${parts[2]}`;
    }
  }

  const khmerMonths = ['មករា', 'កុម្ភៈ', 'មីនា', 'មេសា', 'ឧសភា', 'មិថុនា', 'កក្កដា', 'សីហា', 'កញ្ញា', 'តុលា', 'វិច្ឆិកា', 'ធ្នូ'];
  let monthLabel = 'ខែ';
  if (mode === 'month') {
    const mKey = execHierarchyFilterState.selectedMonth || currentIsoMonth;
    const parts = mKey.split('-');
    const mIndex = parseInt(parts[1], 10) - 1;
    monthLabel = `ខែ ${khmerMonths[mIndex] || parts[1]}`;
  }

  let yearLabel = 'ឆ្នាំ';
  if (mode === 'year') {
    const yStr = execHierarchyFilterState.selectedYear || currentIsoYear;
    yearLabel = `ឆ្នាំ ${yStr}`;
  }

  const activeBtnClasses = 'accent-solid-btn shadow-md text-white';
  const inactiveBtnClasses = 'text-slate-400 hover:text-white';

  container.innerHTML = `
    <div class="flex items-center gap-1 bg-black/40 p-1 rounded-2xl border border-white/5 w-full relative">
      <!-- 1. Day Pill -->
      <div class="relative flex-1">
        <button onclick="toggleExecDayDropdown(event)" id="exec-filter-btn-day" 
                class="w-full py-1.5 px-2 rounded-xl text-xs font-semibold text-center transition dock-btn flex items-center justify-center gap-1 ${mode === 'day' ? activeBtnClasses : inactiveBtnClasses}">
          <span id="exec-day-pill-label">${dayLabel}</span>
          <i data-lucide="chevron-down" class="w-3 h-3 opacity-80"></i>
        </button>

        <div id="exec-day-dropdown-menu" 
             class="hidden absolute top-full left-0 mt-2 w-72 max-w-[calc(100vw-2rem)] bg-[#0C1425]/98 backdrop-blur-3xl border border-white/20 rounded-3xl shadow-2xl p-3.5 z-50 flex flex-col gap-2.5 font-sans ring-1 ring-white/10 animate-fade-in">
        </div>
      </div>

      <!-- 2. Month Pill -->
      <div class="relative flex-1">
        <button onclick="toggleExecMonthDropdown(event)" id="exec-filter-btn-month" 
                class="w-full py-1.5 px-2 rounded-xl text-xs font-semibold text-center transition dock-btn flex items-center justify-center gap-1 ${mode === 'month' ? activeBtnClasses : inactiveBtnClasses}">
          <span id="exec-month-pill-label">${monthLabel}</span>
          <i data-lucide="chevron-down" class="w-3 h-3 opacity-80"></i>
        </button>

        <div id="exec-month-dropdown-menu" 
             class="hidden absolute top-full left-1/2 -translate-x-1/2 sm:left-0 sm:translate-x-0 mt-2 w-48 bg-[#0C1425]/98 backdrop-blur-3xl border border-white/20 rounded-2xl shadow-2xl p-1.5 z-50 flex flex-col gap-0.5 font-sans ring-1 ring-white/10 animate-fade-in">
        </div>
      </div>

      <!-- 3. Year Pill -->
      <div class="relative flex-1">
        <button onclick="toggleExecYearDropdown(event)" id="exec-filter-btn-year" 
                class="w-full py-1.5 px-2 rounded-xl text-xs font-semibold text-center transition dock-btn flex items-center justify-center gap-1 ${mode === 'year' ? activeBtnClasses : inactiveBtnClasses}">
          <span id="exec-year-pill-label">${yearLabel}</span>
          <i data-lucide="chevron-down" class="w-3 h-3 opacity-80"></i>
        </button>

        <div id="exec-year-dropdown-menu" 
             class="hidden absolute top-full right-0 mt-2 w-36 bg-[#0C1425]/98 backdrop-blur-3xl border border-white/20 rounded-2xl shadow-2xl p-1.5 z-50 flex flex-col gap-0.5 font-sans ring-1 ring-white/10 animate-fade-in">
        </div>
      </div>

      <!-- 4. All Period Pill -->
      <button onclick="setExecPeriodFilter('all', null, event)" id="exec-filter-btn-all" 
              class="flex-1 py-1.5 px-2 rounded-xl text-xs font-semibold text-center transition dock-btn flex items-center justify-center gap-0.5 ${mode === 'all' ? activeBtnClasses : inactiveBtnClasses}">
        <span>ទាំងអស់</span>
        <i data-lucide="layers" class="w-3 h-3 opacity-80"></i>
      </button>
    </div>
  `;

  if (window.lucide) window.lucide.createIcons();
}

function getPreviousMonthKey(monthKey) {
  if (!monthKey || typeof monthKey !== 'string' || !monthKey.includes('-')) {
    const now = new Date();
    const y = now.getFullYear();
    const m = now.getMonth(); // 0-indexed, so current month - 1
    if (m === 0) return `${y - 1}-12`;
    return `${y}-${String(m).padStart(2, '0')}`;
  }
  const parts = monthKey.split('-');
  let y = parseInt(parts[0], 10);
  let m = parseInt(parts[1], 10);
  m -= 1;
  if (m < 1) {
    m = 12;
    y -= 1;
  }
  return `${y}-${String(m).padStart(2, '0')}`;
}

function calculateMoMGrowth(curVal, prevVal) {
  const cur = Number(curVal) || 0;
  const prev = Number(prevVal) || 0;
  if (prev === 0 && cur === 0) return null;
  if (prev === 0 && cur > 0) {
    return {
      percent: 100,
      text: '+100%',
      isPositive: true,
      isNew: true
    };
  }
  const diff = cur - prev;
  const pct = (diff / prev) * 100;
  const rounded = Math.round(pct * 10) / 10;
  const isPos = rounded >= 0;
  return {
    percent: rounded,
    text: `${isPos ? '+' : ''}${rounded.toFixed(1)}%`,
    isPositive: isPos,
    isNew: false
  };
}

function renderMoMBadgeHtml(growth, options = {}) {
  if (!growth) return '';
  const isPos = growth.isPositive;
  const colorClass = isPos
    ? 'text-emerald-400 bg-emerald-500/10 border-emerald-500/25'
    : 'text-rose-400 bg-rose-500/10 border-rose-500/25';
  const arrow = isPos ? '↗' : '↘';
  const extraClass = options.extraClass || '';
  const tooltip = options.tooltip || `ធៀបនឹងខែមុន (${growth.text})`;
  return `<span class="inline-flex items-center gap-0.5 px-1.5 py-0.2 rounded font-mono text-[9px] font-bold border ${colorClass} ${extraClass}" title="${escapeHtml(tooltip)}"><span>${growth.text}</span><span class="text-[9.5px] leading-none">${arrow}</span></span>`;
}

function getExecMonthStatsMap(d, targetMonth) {
  if (!d || !targetMonth) return {};
  const allOrders = (Array.isArray(d.bostarTrackSales)) ? d.bostarTrackSales : [];
  const filtered = allOrders.filter(o => o.isoDate && o.isoDate.startsWith(targetMonth));
  const statsMap = {};
  filtered.forEach(o => {
    const sName = (o.seller || '').trim();
    if (!sName) return;
    if (!statsMap[sName]) statsMap[sName] = { boxes: 0, orders: 0 };
    const b = Number(o.totalBoxQty || o.boxes || 0);
    statsMap[sName].boxes += b;
    statsMap[sName].orders += 1;
  });
  return statsMap;
}

function getExecFilteredStats(d) {
  const mode = execHierarchyFilterState.mode || 'all';
  if (mode === 'all') return null;

  const allOrders = (d && Array.isArray(d.bostarTrackSales)) ? d.bostarTrackSales : [];
  const now = new Date();
  const currentIsoDay = getLocalIsoDate(now);
  const currentIsoMonth = currentIsoDay.slice(0, 7);
  const currentIsoYear = currentIsoDay.slice(0, 4);

  let filtered = allOrders;
  if (mode === 'day') {
    const targetDay = execHierarchyFilterState.selectedDate || currentIsoDay;
    filtered = allOrders.filter(o => o.isoDate === targetDay);
  } else if (mode === 'month') {
    const targetMonth = execHierarchyFilterState.selectedMonth || currentIsoMonth;
    filtered = allOrders.filter(o => o.isoDate && o.isoDate.startsWith(targetMonth));
  } else if (mode === 'year') {
    const targetYear = execHierarchyFilterState.selectedYear || currentIsoYear;
    filtered = allOrders.filter(o => o.isoDate && o.isoDate.startsWith(targetYear));
  }

  const statsMap = {};
  filtered.forEach(o => {
    const sName = (o.seller || '').trim();
    if (!sName) return;
    if (!statsMap[sName]) statsMap[sName] = { boxes: 0, orders: 0 };
    const b = Number(o.totalBoxQty || o.boxes || 0);
    statsMap[sName].boxes += b;
    statsMap[sName].orders += 1;
  });
  return statsMap;
}

