function setExpensesPeriodFilter(mode, val, event) {
  if (event) event.stopPropagation();
  closeAllExpensesDropdowns();
  expensesFilterState.mode = mode;
  applyExpensesFilterAndRender();
}

function applyExpensesFilterAndRender() {
  const d = DataService.data;
  if (!d) return;

  const now = new Date();
  const currentIsoDay = getLocalIsoDate(now);
  const currentIsoMonth = currentIsoDay.slice(0, 7);
  const currentIsoYear = currentIsoDay.slice(0, 4);

  const btnDay = document.getElementById('expenses-filter-btn-day');
  const btnMonth = document.getElementById('expenses-filter-btn-month');
  const btnYear = document.getElementById('expenses-filter-btn-year');
  const btnAll = document.getElementById('expenses-filter-btn-all');

  const lblDay = document.getElementById('expenses-day-pill-label');
  const lblMonth = document.getElementById('expenses-month-pill-label');
  const lblYear = document.getElementById('expenses-year-pill-label');
  const subtitle = document.getElementById('expenses-modal-subtitle');

  const activeBtnClasses = ['accent-solid-btn', 'shadow-md', 'text-white'];
  const inactiveBtnClasses = ['text-slate-400', 'hover:text-white'];

  function setPillActive(btn) {
    [btnDay, btnMonth, btnYear, btnAll].forEach(b => {
      if (!b) return;
      if (b === btn) {
        b.classList.add(...activeBtnClasses);
        b.classList.remove(...inactiveBtnClasses);
      } else {
        b.classList.remove(...activeBtnClasses);
        b.classList.add(...inactiveBtnClasses);
      }
    });
  }

  let filtered = d.expenses || [];
  let periodLabel = 'ទាំងអស់';

  if (expensesFilterState.mode === 'day') {
    setPillActive(btnDay);
    const targetDay = expensesFilterState.selectedDate || currentIsoDay;
    filtered = (d.expenses || []).filter(e => e.isoDate === targetDay);
    const dayNum = targetDay.slice(8, 10);
    if (lblDay) lblDay.textContent = `ថ្ងៃទី ${parseInt(dayNum, 10)}`;
    periodLabel = `ថ្ងៃ ${displayDDMMYYYY(targetDay)}`;
  } else if (expensesFilterState.mode === 'month') {
    setPillActive(btnMonth);
    const targetMonth = expensesFilterState.selectedMonth || currentIsoMonth;
    filtered = (d.expenses || []).filter(e => e.isoDate && e.isoDate.startsWith(targetMonth));
    const parts = targetMonth.split('-');
    if (lblMonth) lblMonth.textContent = `ខែ ${parseInt(parts[1], 10)}`;
    periodLabel = `ខែ ${parts[1]}/${parts[0]}`;
  } else if (expensesFilterState.mode === 'year') {
    setPillActive(btnYear);
    const targetYear = expensesFilterState.selectedYear || currentIsoYear;
    filtered = (d.expenses || []).filter(e => e.isoDate && e.isoDate.startsWith(targetYear));
    if (lblYear) lblYear.textContent = `ឆ្នាំ ${targetYear}`;
    periodLabel = `ឆ្នាំ ${targetYear}`;
  } else {
    // Mode is 'all'
    setPillActive(btnAll);
    if (lblDay) lblDay.textContent = 'ថ្ងៃទី';
    if (lblMonth) lblMonth.textContent = 'ខែ';
    if (lblYear) lblYear.textContent = 'ឆ្នាំ';
    periodLabel = 'ទាំងអស់';
  }

  // Strict sorting from latest to earliest (Day 31 ➔ 01, Year latest ➔ earliest, highest rowIndex first)
  const sortedExpenses = [...filtered].sort((a, b) => {
    const cmp = (b.isoDate || '').localeCompare(a.isoDate || '');
    if (cmp !== 0) return cmp;
    return (b.rowIndex || 0) - (a.rowIndex || 0);
  });
  const totalAmount = sortedExpenses.reduce((sum, e) => sum + (e.amount || 0), 0);

  expensesFilterState.currentPeriodLabel = periodLabel;
  if (subtitle) {
    subtitle.textContent = periodLabel === 'ទាំងអស់'
      ? `ចំណាយទាំងអស់ (${sortedExpenses.length} មុខ)`
      : `ចំណាយតាម ${periodLabel} (${sortedExpenses.length} មុខ)`;
  }

  currentLoadedExpenses = sortedExpenses;

  // If search query is currently active in the input, apply search filter
  const searchInput = document.getElementById('expenses-modal-search-input');
  if (searchInput && searchInput.value.trim()) {
    filterExpensesModalList();
  } else {
    renderExpensesModalRows(currentLoadedExpenses);
  }

  if (window.lucide) window.lucide.createIcons();
}

function openExpensesModal(mode = false, fromDrawer = false) {
  if (!window.navOpenedFromDrawer) window.navOpenedFromDrawer = {};
  window.navOpenedFromDrawer.expenses = !!fromDrawer;
  const d = DataService.data;
  if (!d) return;

  const modal = document.getElementById('expenses-modal');
  const listEl = document.getElementById('expenses-modal-list');

  const now = new Date();
  const currentIsoDay = getLocalIsoDate(now);
  const currentIsoMonth = currentIsoDay.slice(0, 7);
  const currentIsoYear = currentIsoDay.slice(0, 4);

  // Initialize expensesFilterState based on mode or appState
  if (mode === 'all') {
    expensesFilterState.mode = 'all';
    expensesFilterState.selectedDate = currentIsoDay;
    expensesFilterState.selectedMonth = currentIsoMonth;
    expensesFilterState.selectedYear = currentIsoYear;
    expensesFilterState.calYear = now.getFullYear();
    expensesFilterState.calMonth = now.getMonth() + 1;
  } else if (mode === true || mode === 'month') {
    expensesFilterState.mode = 'month';
    expensesFilterState.selectedMonth = appState.selectedMonthKey || currentIsoMonth;
    const parts = expensesFilterState.selectedMonth.split('-');
    expensesFilterState.calYear = parseInt(parts[0], 10);
    expensesFilterState.calMonth = parseInt(parts[1], 10);
  } else if (mode === 'year') {
    expensesFilterState.mode = 'year';
    expensesFilterState.selectedYear = appState.selectedYear ? String(appState.selectedYear) : currentIsoYear;
    expensesFilterState.calYear = parseInt(expensesFilterState.selectedYear, 10);
  } else if (mode === 'day') {
    expensesFilterState.mode = 'day';
    if (appState.daySubFilter === 'specific' && appState.specificDate) {
      expensesFilterState.selectedDate = appState.specificDate;
    } else if (appState.daySubFilter === 'yesterday') {
      expensesFilterState.selectedDate = getYesterdayIso();
    } else {
      expensesFilterState.selectedDate = currentIsoDay;
    }
    const parts = expensesFilterState.selectedDate.split('-');
    expensesFilterState.calYear = parseInt(parts[0], 10);
    expensesFilterState.calMonth = parseInt(parts[1], 10);
  } else {
    // Default drill-down based on current appState
    if (appState.periodFilter === 'month') {
      expensesFilterState.mode = 'month';
      expensesFilterState.selectedMonth = appState.selectedMonthKey || currentIsoMonth;
      const parts = expensesFilterState.selectedMonth.split('-');
      expensesFilterState.calYear = parseInt(parts[0], 10);
      expensesFilterState.calMonth = parseInt(parts[1], 10);
    } else if (appState.periodFilter === 'year') {
      expensesFilterState.mode = 'year';
      expensesFilterState.selectedYear = appState.selectedYear ? String(appState.selectedYear) : currentIsoYear;
      expensesFilterState.calYear = parseInt(expensesFilterState.selectedYear, 10);
    } else {
      // today / specific / yesterday / custom
      expensesFilterState.mode = 'day';
      if (appState.daySubFilter === 'specific' && appState.specificDate) {
        expensesFilterState.selectedDate = appState.specificDate;
      } else if (appState.daySubFilter === 'yesterday') {
        expensesFilterState.selectedDate = getYesterdayIso();
      } else {
        expensesFilterState.selectedDate = currentIsoDay;
      }
      const parts = expensesFilterDateParts(expensesFilterState.selectedDate);
      expensesFilterState.calYear = parts.year;
      expensesFilterState.calMonth = parts.month;
    }
  }

  // Ensure search is collapsed initially
  const searchContainer = document.getElementById('expenses-modal-search-container');
  const searchInput = document.getElementById('expenses-modal-search-input');
  const clearBtn = document.getElementById('expenses-modal-clear-search');
  const searchToggleBtn = document.getElementById('expenses-modal-search-toggle-btn');
  if (searchContainer) searchContainer.classList.add('hidden');
  if (searchInput) searchInput.value = '';
  if (clearBtn) clearBtn.classList.add('hidden');
  if (searchToggleBtn) {
    searchToggleBtn.classList.remove('bg-orange-500/20', 'text-white', 'border-orange-500/40');
    searchToggleBtn.classList.add('bg-white/5', 'text-orange-400', 'border-white/10');
  }
  expensesFilterState.isSearchOpen = false;
  expensesFilterState.viewTab = 'list';
  expensesFilterState.activeCategoryFilter = 'all';

  closeAllExpensesDropdowns();
  applyExpensesFilterAndRender();

  const expFilterBar = document.getElementById('expenses-modal-date-filter-bar');
  if (expFilterBar) expFilterBar.classList.remove('filter-hidden');

  modal.classList.remove('hidden');
  setDockVisible(true);
  if (listEl && typeof hookScrollableForDock === 'function') hookScrollableForDock(listEl, false);
  if (appState.fontFamily) modal.classList.add(appState.fontFamily);
  if (window.lucide) window.lucide.createIcons();
}

function expensesFilterDateParts(iso) {
  if (!iso) {
    const d = new Date();
    return { year: d.getFullYear(), month: d.getMonth() + 1 };
  }
  const parts = iso.split('-');
  return { year: parseInt(parts[0], 10), month: parseInt(parts[1], 10) };
}

// iOS / Telegram Category Styling & Color Mapping
function getExpenseCategoryStyle(name, index) {
  const n = (name || '').toLowerCase();
  if (n.includes('ads') || n.includes('boost') || n.includes('fb') || n.includes('tiktok') || n.includes('facebook')) {
    return { icon: 'megaphone', color: '#3B82F6', bg: 'bg-blue-500/20', text: 'text-blue-400', border: 'border-blue-500/30' };
  }
  if (n.includes('ហូប') || n.includes('បាយ') || n.includes('ម្ហូប') || n.includes('អាហារ') || n.includes('ញ៉ាំ')) {
    return { icon: 'utensils', color: '#10B981', bg: 'bg-emerald-500/20', text: 'text-emerald-400', border: 'border-emerald-500/30' };
  }
  if (n.includes('កាហ្វេ')) {
    return { icon: 'coffee', color: '#F59E0B', bg: 'bg-amber-500/20', text: 'text-amber-400', border: 'border-amber-500/30' };
  }
  if (n.includes('កម្សាន្ត') || n.includes('ចំណង់') || n.includes('នំ') || n.includes('លេង')) {
    return { icon: 'sparkles', color: '#F59E0B', bg: 'bg-amber-500/20', text: 'text-amber-400', border: 'border-amber-500/30' };
  }
  if (n.includes('ថេរ') || n.includes('ផ្ទះ') || n.includes('បន្ទប់') || n.includes('ទឹកភ្លើង') || n.includes('ជួល')) {
    return { icon: 'home', color: '#F43F5E', bg: 'bg-rose-500/20', text: 'text-rose-400', border: 'border-rose-500/30' };
  }
  if (n.includes('ទូរស័ព្ទ') || n.includes('net') || n.includes('wifi') || n.includes('internet') || n.includes('កាត')) {
    return { icon: 'wifi', color: '#8B5CF6', bg: 'bg-purple-500/20', text: 'text-purple-400', border: 'border-purple-500/30' };
  }
  if (n.includes('ដឹក') || n.includes('សាំង') || n.includes('កង់បី') || n.includes('passapp') || n.includes('ឡាន') || n.includes('ធ្វើដំណើរ')) {
    return { icon: 'truck', color: '#FB923C', bg: 'bg-orange-500/20', text: 'text-orange-400', border: 'border-orange-500/30' };
  }
  if (n.includes('សុខភាព') || n.includes('ថ្នាំ') || n.includes('ពេទ្យ')) {
    return { icon: 'heart-pulse', color: '#EC4899', bg: 'bg-pink-500/20', text: 'text-pink-400', border: 'border-pink-500/30' };
  }
  if (n.includes('ទាន') || n.includes('បន្ទាន់') || n.includes('សង្គ្រោះ')) {
    return { icon: 'hand-heart', color: '#14B8A6', bg: 'bg-teal-500/20', text: 'text-teal-400', border: 'border-teal-500/30' };
  }
  if (n.includes('វិនិយោគ') || n.includes('ទំនិញ') || n.includes('ស្តុក') || n.includes('អភិវឌ្ឍន៍')) {
    return { icon: 'trending-up', color: '#06B6D4', bg: 'bg-cyan-500/20', text: 'text-cyan-400', border: 'border-cyan-500/30' };
  }
  const fallbackColors = [
    { color: '#6366F1', bg: 'bg-indigo-500/20', text: 'text-indigo-400', border: 'border-indigo-500/30', icon: 'receipt' },
    { color: '#84CC16', bg: 'bg-lime-500/20', text: 'text-lime-400', border: 'border-lime-500/30', icon: 'tag' },
    { color: '#0EA5E9', bg: 'bg-sky-500/20', text: 'text-sky-400', border: 'border-sky-500/30', icon: 'layers' },
    { color: '#D946EF', bg: 'bg-fuchsia-500/20', text: 'text-fuchsia-400', border: 'border-fuchsia-500/30', icon: 'bookmark' }
  ];
  return fallbackColors[index % fallbackColors.length];
}

function setExpensesViewTab(tab) {
  expensesFilterState.viewTab = tab;
  updateExpensesViewTabButtons();
  const searchInput = document.getElementById('expenses-modal-search-input');
  if (searchInput && searchInput.value.trim()) {
    filterExpensesModalList();
  } else {
    renderExpensesModalRows(currentLoadedExpenses);
  }
}

function updateExpensesViewTabButtons() {
  const btnBreakdown = document.getElementById('expenses-tab-breakdown-btn');
  const btnList = document.getElementById('expenses-tab-list-btn');
  const footer = document.getElementById('expenses-modal-footer');

  if (expensesFilterState.viewTab === 'breakdown') {
    if (btnBreakdown) {
      btnBreakdown.className = 'flex-1 py-1 px-2 rounded-xl text-center transition flex items-center justify-center gap-1.5 bg-orange-500 text-white font-bold shadow-sm';
    }
    if (btnList) {
      btnList.className = 'flex-1 py-1 px-2 rounded-xl text-center transition flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-medium';
    }
    if (footer) footer.classList.add('hidden');
  } else {
    if (btnBreakdown) {
      btnBreakdown.className = 'flex-1 py-1 px-2 rounded-xl text-center transition flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-medium';
    }
    if (btnList) {
      btnList.className = 'flex-1 py-1 px-2 rounded-xl text-center transition flex items-center justify-center gap-1.5 bg-orange-500 text-white font-bold shadow-sm';
    }
    if (footer) footer.classList.remove('hidden');
  }
}

function toggleExpenseCategoryAccordion(catName, catId) {
  const isExp = !!expensesFilterState.expandedCategories[catName];
  expensesFilterState.expandedCategories[catName] = !isExp;

  const subEl = document.getElementById(`exp-subitems-${catId}`);
  const chevEl = document.getElementById(`exp-chevron-${catId}`);
  if (subEl) {
    if (!isExp) subEl.classList.remove('hidden');
    else subEl.classList.add('hidden');
  }
  if (chevEl) {
    if (!isExp) chevEl.classList.add('rotate-180', 'text-orange-400');
    else chevEl.classList.remove('rotate-180', 'text-orange-400');
  }
  if (window.lucide) window.lucide.createIcons();
}

function filterExpensesByCategory(encodedCatName) {
  const catName = decodeURIComponent(encodedCatName);
  if (catName === 'all') {
    expensesFilterState.activeCategoryFilter = 'all';
  } else if (expensesFilterState.activeCategoryFilter && expensesFilterState.activeCategoryFilter.toLowerCase() === catName.toLowerCase()) {
    expensesFilterState.activeCategoryFilter = 'all'; // toggle back to all
  } else {
    expensesFilterState.activeCategoryFilter = catName;
  }
  const searchInput = document.getElementById('expenses-modal-search-input');
  if (searchInput && searchInput.value.trim()) {
    filterExpensesModalList();
  } else {
    renderExpensesModalRows(currentLoadedExpenses);
  }
}

function renderExpensesBreakdownView(items, totalAmount, listEl) {
  // 1. Group items by category
  const categoryMap = {};
  items.forEach(e => {
    const cat = (e.category || 'ផ្សេងៗ').trim() || 'ផ្សេងៗ';
    const amt = Number(e.amount) || 0;
    if (!categoryMap[cat]) {
      categoryMap[cat] = {
        name: cat,
        total: 0,
        items: []
      };
    }
    categoryMap[cat].total += amt;
    categoryMap[cat].items.push(e);
  });

  const allCategories = Object.values(categoryMap).sort((a, b) => b.total - a.total);
  allCategories.forEach((cat, idx) => {
    cat.style = getExpenseCategoryStyle(cat.name, idx);
    cat.pct = totalAmount > 0 ? (cat.total / totalAmount) * 100 : 0;
  });

  const activeCat = expensesFilterState.activeCategoryFilter || 'all';
  const displayedCategories = (activeCat && activeCat !== 'all')
    ? allCategories.filter(c => c.name.toLowerCase() === activeCat.toLowerCase())
    : allCategories;

  // Donut Chart SVG calculations
  const radius = 78;
  const strokeWidth = 26;
  const circumference = 2 * Math.PI * radius; // ~490.088
  let accumulatedLen = 0;
  let accumulatedPct = 0;
  let slicesSvg = '';
  let labelsSvg = '';

  allCategories.forEach((cat) => {
    const strokeLen = (cat.pct / 100) * circumference;
    const offset = -accumulatedLen;

    slicesSvg += `
      <circle cx="120" cy="120" r="${radius}" fill="none"
              stroke="${cat.style.color}"
              stroke-width="${strokeWidth}"
              stroke-dasharray="${strokeLen.toFixed(2)} ${(circumference - strokeLen).toFixed(2)}"
              stroke-dashoffset="${offset.toFixed(2)}"
              class="transition-all duration-500 cursor-pointer hover:opacity-85"
              onclick="filterExpensesByCategory('${encodeURIComponent(cat.name)}')" />
    `;

    // Percentage labels directly on slices (if pct >= 6%)
    if (cat.pct >= 6) {
      const startAngle = (accumulatedPct / 100) * 360;
      const endAngle = startAngle + (cat.pct / 100) * 360;
      const midAngle = (startAngle + endAngle) / 2;
      const angleRad = (midAngle - 90) * (Math.PI / 180);
      const lx = 120 + radius * Math.cos(angleRad);
      const ly = 120 + radius * Math.sin(angleRad);

      labelsSvg += `
        <text x="${lx.toFixed(1)}" y="${(ly + 3.5).toFixed(1)}"
              text-anchor="middle"
              fill="#FFFFFF"
              font-size="${cat.pct >= 10 ? '11' : '9.5'}"
              font-weight="bold"
              font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
              style="filter: drop-shadow(0 1px 2px rgba(0,0,0,0.95)); pointer-events: none;">
          ${cat.pct.toFixed(1)}%
        </text>
      `;
    }

    accumulatedLen += strokeLen;
    accumulatedPct += cat.pct;
  });

  const periodLabel = expensesFilterState.currentPeriodLabel || 'ទាំងអស់';

  listEl.innerHTML = `
    <!-- 1. Top Donut Chart Container (iOS Storage Style) -->
    <div class="pt-2 pb-1 flex flex-col items-center">
      <div class="relative w-56 h-56 mx-auto flex items-center justify-center">
        <!-- Rotated SVG for Slices -->
        <svg viewBox="0 0 240 240" class="w-full h-full transform -rotate-90 select-none">
          <circle cx="120" cy="120" r="${radius}" fill="none"
                  stroke="rgba(255,255,255,0.06)"
                  stroke-width="${strokeWidth}" />
          ${slicesSvg}
        </svg>
        <!-- Unrotated Overlay for Crisp Upright Percentages -->
        <svg viewBox="0 0 240 240" class="absolute inset-0 w-full h-full pointer-events-none select-none">
          ${labelsSvg}
        </svg>
        <!-- Center Total & Label -->
        <div class="absolute inset-0 flex flex-col items-center justify-center text-center pointer-events-none select-none">
          <span class="text-white font-mono font-bold text-2xl tracking-tight leading-none drop-shadow-lg">
            ${formatUSD(totalAmount)}
          </span>
          <span class="text-[10px] sm:text-[11px] font-sans font-bold text-slate-300 uppercase tracking-wider mt-1.5">
            ចំណាយសរុប
          </span>
          <span class="text-[10px] font-mono text-slate-400 mt-0.5">
            ${items.length} មុខ
          </span>
        </div>
      </div>

      <!-- Title & Subtitle -->
      <div class="text-center mt-2 mb-2">
        <h4 class="text-sm font-bold text-white tracking-tight">ការបែងចែកចំណាយ (Expense Breakdown)</h4>
        <p class="text-[11px] text-slate-400 mt-0.5 font-mono">${periodLabel} • សរុប ${items.length} មុខ</p>
      </div>
    </div>

    <!-- 2. Sticky Category Filter Pills Bar (ស្អិតជាប់ខាងលើ មិនរត់បាត់ពេល Scroll ឬពេលជ្រើសរើស) -->
    <div id="expense-category-pills-sticky-bar" class="sticky top-0 z-30 bg-[#070D18]/95 backdrop-blur-xl -mx-3.5 px-3.5 py-2 border-b border-white/10 mb-3 shadow-lg">
      <div id="expense-category-pills-container" class="w-full flex items-center gap-1.5 p-1 rounded-2xl bg-black/50 border border-white/10 overflow-x-auto no-scrollbar text-xs font-semibold">
        <button type="button" onclick="filterExpensesByCategory('all')"
                ${activeCat === 'all' ? 'id="active-expense-cat-pill"' : ''}
                class="py-1.5 px-3 rounded-xl transition whitespace-nowrap active:scale-95 shrink-0 ${activeCat === 'all' ? 'bg-orange-500 text-white font-bold shadow-md shadow-orange-500/30' : 'text-slate-400 hover:text-white'}">
          ទាំងអស់ (${items.length})
        </button>
        ${allCategories.map(c => {
          const isSelected = activeCat.toLowerCase() === c.name.toLowerCase();
          return `
            <button type="button" onclick="filterExpensesByCategory('${encodeURIComponent(c.name)}')"
                    ${isSelected ? 'id="active-expense-cat-pill"' : ''}
                    class="py-1.5 px-2.5 rounded-xl transition whitespace-nowrap active:scale-95 shrink-0 flex items-center gap-1.5 ${isSelected ? 'bg-white/25 text-white font-bold shadow-md ring-2 ring-orange-400/80 border border-white/30' : 'text-slate-400 hover:text-white border border-transparent'}">
              <span class="w-2 h-2 rounded-full shrink-0 ${isSelected ? 'animate-pulse' : ''}" style="background-color: ${c.style.color};"></span>
              <span>${c.name}</span>
            </button>
          `;
        }).join('')}
      </div>
    </div>

    <!-- 2. iOS Telegram-Style Category Accordion List -->
    <div class="rounded-3xl bg-[#0D1525]/90 border border-white/10 divide-y divide-white/5 overflow-hidden shadow-2xl">
      ${displayedCategories.map((c, idx) => {
        const isExpanded = !!expensesFilterState.expandedCategories[c.name] || (activeCat.toLowerCase() === c.name.toLowerCase());
        const catId = `cat-${idx}`;
        return `
          <div class="category-accordion-group">
            <!-- Header Row -->
            <div onclick="toggleExpenseCategoryAccordion('${c.name.replace(/'/g, "\\'")}', '${catId}')"
                 class="p-3.5 flex items-center justify-between cursor-pointer hover:bg-white/[0.04] active:bg-white/[0.08] transition select-none">
              <div class="flex items-center gap-3 min-w-0 pr-2">
                <div class="w-10 h-10 rounded-2xl ${c.style.bg} ${c.style.text} border ${c.style.border} flex items-center justify-center shrink-0 shadow-md">
                  <i data-lucide="${c.style.icon}" class="w-5 h-5"></i>
                </div>
                <div class="min-w-0">
                  <div class="flex items-center gap-2">
                    <span class="font-bold text-xs sm:text-sm text-white truncate">${c.name}</span>
                    <span class="text-[11px] font-mono text-slate-400 font-semibold">${c.pct.toFixed(1)}%</span>
                  </div>
                  <p class="text-[10px] text-slate-500 font-mono mt-0.5">${c.items.length} ប្រតិបត្តិការ</p>
                </div>
              </div>
              <div class="flex items-center gap-2 shrink-0">
                <span class="font-mono text-rose-400 font-bold text-xs sm:text-sm whitespace-nowrap">${formatUSD(c.total)}</span>
                <i data-lucide="chevron-down" id="exp-chevron-${catId}"
                   class="w-4 h-4 text-slate-400 transition-transform duration-200 ${isExpanded ? 'rotate-180 text-orange-400' : ''}"></i>
              </div>
            </div>

            <!-- Accordion Sub-items List (Transactions with Swipe to Edit/Delete) -->
            <div id="exp-subitems-${catId}" class="${isExpanded ? '' : 'hidden'} bg-black/40 border-t border-white/5 divide-y divide-white/5 px-2 py-1.5 animate-fade-in space-y-1">
              ${c.items.map((sub, sIdx) => {
                const globalIdx = currentLoadedExpenses ? currentLoadedExpenses.indexOf(sub) : -1;
                return `
                  <div onclick="openExpenseActionSheet(${globalIdx})"
                       title="ចុចដើម្បីកែប្រែ ឬលុបចំណាយ"
                       class="py-2.5 px-2.5 flex items-center justify-between text-xs hover:bg-white/[0.05] active:bg-white/[0.08] active:scale-[0.99] rounded-xl transition cursor-pointer select-none">
                    <div class="flex items-center gap-2.5 min-w-0 pr-2">
                      <span class="w-5 h-5 rounded-lg bg-white/5 text-slate-400 font-mono text-[10px] font-bold flex items-center justify-center shrink-0">
                        ${sIdx + 1}
                      </span>
                      <div class="min-w-0">
                        <p class="text-white font-medium text-xs truncate leading-tight">${sub.description || sub.category}</p>
                        <div class="flex items-center gap-2 text-[10px] text-slate-400 mt-0.5 font-mono">
                          <span>${sub.date}</span>
                          ${sub.time ? `<span class="text-amber-300">⏰ ${sub.time}</span>` : ''}
                        </div>
                      </div>
                    </div>
                    <span class="font-mono text-rose-400 font-bold text-xs shrink-0 whitespace-nowrap">${formatUSD(sub.amount)}</span>
                  </div>
                `;
              }).join('')}
            </div>
          </div>
        `;
      }).join('')}
    </div>

    <!-- 3. Bottom Helper Hint (matching screenshot) -->
    <p class="text-[11px] text-slate-500 text-center pt-3 pb-1 italic flex items-center justify-center gap-1.5">
      <i data-lucide="info" class="w-3.5 h-3.5 opacity-70"></i>
      <span>ចុចលើចំណាយណាមួយដើម្បី កែប្រែ ឬលុប</span>
    </p>
  `;

  if (window.lucide) window.lucide.createIcons();

  // Keep selected category pill visible in view horizontally
  setTimeout(() => {
    const activePill = document.getElementById('active-expense-cat-pill');
    if (activePill) {
      try {
        activePill.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
      } catch (_) {
        try { activePill.scrollIntoView(false); } catch (__) {}
      }
    }
  }, 20);
}

// Global Swipe & Long-Press Controller for Expenses
let currentExpenseActionTarget = null;
let activeSwipedExpenseEl = null;
let expenseTouchStartX = 0;
let expenseTouchStartY = 0;
let expenseCurrentTranslateX = 0;
let expenseLongPressTimer = null;
let isExpenseSwiping = false;

function resetAllSwipedExpenses() {
  document.querySelectorAll('.swipe-expense-item').forEach(el => {
    el.style.transform = 'translateX(0px)';
  });
  activeSwipedExpenseEl = null;
}

function handleExpenseTouchStart(e, el) {
  if (activeSwipedExpenseEl && activeSwipedExpenseEl !== el) {
    resetAllSwipedExpenses();
  }

  const touch = e.touches ? e.touches[0] : e;
  expenseTouchStartX = touch.clientX;
  expenseTouchStartY = touch.clientY;
  expenseCurrentTranslateX = 0;
  isExpenseSwiping = false;

  clearTimeout(expenseLongPressTimer);
  const idx = parseInt(el.getAttribute('data-expense-idx') || '-1', 10);
  expenseLongPressTimer = setTimeout(() => {
    clearTimeout(expenseLongPressTimer);
    expenseLongPressTimer = null;
    isExpenseSwiping = false;
    el.style.transform = 'scale(0.97)';
    setTimeout(() => {
      el.style.transform = 'translateX(0px)';
      if (idx >= 0) openExpenseActionSheet(idx);
    }, 140);
  }, 480);
}

function handleExpenseTouchMove(e, el) {
  const touch = e.touches ? e.touches[0] : e;
  const dx = touch.clientX - expenseTouchStartX;
  const dy = touch.clientY - expenseTouchStartY;

  if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
    clearTimeout(expenseLongPressTimer);
    expenseLongPressTimer = null;
  }

  if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 12) {
    isExpenseSwiping = true;
    if (dx < 0) {
      const clampedX = Math.max(dx, -135);
      el.style.transition = 'none';
      el.style.transform = `translateX(${clampedX}px)`;
      expenseCurrentTranslateX = clampedX;
    } else {
      el.style.transition = 'none';
      el.style.transform = `translateX(0px)`;
      expenseCurrentTranslateX = 0;
    }
  }
}

function handleExpenseTouchEnd(e, el) {
  clearTimeout(expenseLongPressTimer);
  expenseLongPressTimer = null;
  el.style.transition = 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)';

  if (isExpenseSwiping) {
    if (expenseCurrentTranslateX < -45) {
      el.style.transform = 'translateX(-120px)';
      activeSwipedExpenseEl = el;
    } else {
      el.style.transform = 'translateX(0px)';
      if (activeSwipedExpenseEl === el) activeSwipedExpenseEl = null;
    }
  }
  isExpenseSwiping = false;
}

function getExpenseFromTarget(expOrIdx) {
  if (typeof expOrIdx === 'object' && expOrIdx !== null) return expOrIdx;
  const num = parseInt(expOrIdx, 10);
  if (!isNaN(num)) {
    if (DataService.data && Array.isArray(DataService.data.expenses)) {
      const byRow = DataService.data.expenses.find(e => e && e.rowIndex === num);
      if (byRow) return byRow;
    }
    if (currentLoadedExpenses && Array.isArray(currentLoadedExpenses)) {
      const byRowLoaded = currentLoadedExpenses.find(e => e && e.rowIndex === num);
      if (byRowLoaded) return byRowLoaded;
      if (currentLoadedExpenses[num]) return currentLoadedExpenses[num];
    }
    if (DataService.data && Array.isArray(DataService.data.expenses) && DataService.data.expenses[num]) {
      return DataService.data.expenses[num];
    }
  }
  return null;
}

function openEditExpenseModalByRow(rowIndex) {
  const exp = getExpenseFromTarget(rowIndex);
  if (exp) {
    openEditExpenseModal(exp);
  } else {
    console.warn('Expense not found for rowIndex:', rowIndex);
  }
}
window.openEditExpenseModalByRow = openEditExpenseModalByRow;

function openExpenseActionSheet(expOrIdx) {
  const exp = getExpenseFromTarget(expOrIdx);
  if (!exp) return;

  currentExpenseActionTarget = exp;
  const sheet = document.getElementById('expense-action-sheet');
  if (!sheet) return;

  const descEl = document.getElementById('expense-action-desc');
  const dateEl = document.getElementById('expense-action-date');
  const catEl = document.getElementById('expense-action-cat');
  const amtEl = document.getElementById('expense-action-amt');

  if (descEl) descEl.textContent = exp.description || exp.category || 'មុខចំណាយ';
  if (dateEl) dateEl.textContent = exp.date || '';
  if (catEl) catEl.textContent = `• ${exp.category || 'ទូទៅ'}`;
  if (amtEl) amtEl.textContent = formatUSD(exp.amount || 0);

  if (navigator.vibrate) try { navigator.vibrate(20); } catch (_) {}

  sheet.classList.remove('hidden');
  setDockVisible(false);
  if (window.lucide) window.lucide.createIcons();
}

function closeExpenseActionSheet(e) {
  if (e && e.target && e.target.id !== 'expense-action-sheet' && !e.target.closest('button')) return;
  const sheet = document.getElementById('expense-action-sheet');
  if (sheet) sheet.classList.add('hidden');
  if (!isDialogModalOpen()) {
    setDockVisible(true);
  }
}

function triggerEditFromActionSheet() {
  const exp = currentExpenseActionTarget;
  closeExpenseActionSheet();
  if (exp) openEditExpenseModal(exp);
}

function triggerDeleteFromActionSheet() {
  const exp = currentExpenseActionTarget;
  closeExpenseActionSheet();
  if (exp) openExpenseDeleteModal(exp);
}

function openExpenseDeleteModal(expOrIdx) {
  const exp = getExpenseFromTarget(expOrIdx);
  if (!exp) return;

  currentExpenseActionTarget = exp;
  const modal = document.getElementById('expense-delete-modal');
  const msgEl = document.getElementById('expense-delete-msg');
  if (msgEl) {
    const safeDesc = typeof escapeHtml === 'function' ? escapeHtml(exp.description || exp.category) : (exp.description || exp.category);
    msgEl.innerHTML = `តើបងពិតជាចង់លុបចំណាយ <strong>«${safeDesc}»</strong> ចំនួន <strong class="text-rose-400 font-mono">${formatUSD(exp.amount || 0)}</strong> នេះចេញពី Google Sheet មែនទេ?`;
  }
  if (modal) modal.classList.remove('hidden');
  setDockVisible(false);
  if (window.lucide) window.lucide.createIcons();
}

function closeExpenseDeleteModal(e) {
  if (e && e.target && e.target.id !== 'expense-delete-modal' && !e.target.closest('button')) return;
  const modal = document.getElementById('expense-delete-modal');
  if (modal) modal.classList.add('hidden');
  if (!isDialogModalOpen()) {
    setDockVisible(true);
  }
}

async function executeDeleteExpense() {
  const exp = currentExpenseActionTarget;
  if (!exp) return;

  const btn = document.getElementById('btn-confirm-delete-expense');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = `<i data-lucide="loader" class="w-3.5 h-3.5 animate-spin"></i><span>កំពុងលុប...</span>`;
    if (window.lucide) window.lucide.createIcons();
  }

  // 1. Remove from in-memory DataService immediately
  if (DataService.data && Array.isArray(DataService.data.expenses)) {
    const idx = DataService.data.expenses.findIndex(e => 
      (exp.rowIndex && e.rowIndex === exp.rowIndex) || 
      (e.description === exp.description && Math.abs((e.amount || 0) - (exp.amount || 0)) < 0.01 && e.date === exp.date)
    );
    if (idx !== -1) {
      DataService.data.expenses.splice(idx, 1);
      if (DataService.data.meta && DataService.data.meta.totalExpensesCount > 0) {
        DataService.data.meta.totalExpensesCount--;
      }
    }
  }

  // 2. Remove from local storage cache if exists
  try {
    const local = JSON.parse(localStorage.getItem('sd_local_expenses') || '[]');
    const filtered = local.filter(e => !(e.description === exp.description && Math.abs((e.amount || 0) - (exp.amount || 0)) < 0.01));
    localStorage.setItem('sd_local_expenses', JSON.stringify(filtered));
  } catch (_) {}

  // 3. Dispatch to Webhook
  const webhookUrl = getAppsScriptWebhookUrl();
  const activeSheetId = (DataService && typeof DataService.getActiveSheetId === 'function') ? DataService.getActiveSheetId() : '';

  try {
    if (navigator.onLine && webhookUrl && webhookUrl.startsWith('http')) {
      await fetch(webhookUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({
          action: 'delete_expense',
          sheetId: activeSheetId,
          data: {
            rowIndex: exp.rowIndex,
            description: exp.description,
            amount: exp.amount,
            date: exp.date
          }
        })
      });
    }
    showToastNotification(`បានលុបចំណាយ "${exp.description || 'ទូទៅ'}" ជោគជ័យ! 🗑️`);
  } catch (err) {
    console.warn('Delete expense sync warning:', err);
    showToastNotification(`បានលុបចេញពីកម្មវិធី ⚠️`);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `<i data-lucide="trash-2" class="w-3.5 h-3.5"></i><span>លុបចេញ</span>`;
      if (window.lucide) window.lucide.createIcons();
    }
    closeExpenseDeleteModal();
    if (typeof filterExpensesModalList === 'function') {
      const searchInput = document.getElementById('expenses-modal-search-input');
      if (searchInput && searchInput.value.trim()) {
        filterExpensesModalList();
      } else {
        renderExpensesModalRows(currentLoadedExpenses);
      }
    }
    renderCurrentView();
  }
}

function renderExpensesModalRows(items) {
  const listEl = document.getElementById('expenses-modal-list');
  const footer = document.getElementById('expenses-modal-footer');
  if (!listEl) return;
  const totalAmount = items.reduce((sum, e) => sum + (e.amount || 0), 0);
  updateExpensesViewTabButtons();

  if (footer) {
    if (expensesFilterState.viewTab === 'breakdown') {
      footer.classList.add('hidden');
    } else {
      footer.classList.remove('hidden');
      footer.innerHTML = `
        <div class="text-slate-300 font-semibold text-xs">
          ចំនួនសរុប: ${items.length} មុខ
        </div>
        <div class="flex items-center gap-1.5 font-mono font-bold text-sm text-rose-400 text-right">
          <span class="text-[11px] text-slate-400 font-sans font-normal">សរុបទឹកប្រាក់:</span>
          <span>${formatUSD(totalAmount)}</span>
        </div>
      `;
    }
  }

  if (items.length === 0) {
    listEl.innerHTML = `
      <div class="flex flex-col items-center justify-center py-16 text-center space-y-3">
        <div class="w-16 h-16 rounded-3xl bg-white/5 border border-white/10 flex items-center justify-center text-slate-500">
          <i data-lucide="receipt" class="w-8 h-8 opacity-60"></i>
        </div>
        <div>
          <p class="text-sm font-bold text-slate-300">មិនមានទិន្នន័យចំណាយទេ</p>
          <p class="text-xs text-slate-500 mt-0.5">មិនមានប្រតិបត្តិការចំណាយក្នុងចន្លោះពេលនេះឡើយ</p>
        </div>
        <button onclick="openNewExpenseModal()" class="px-4 py-2 rounded-xl bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 border border-rose-500/30 text-xs font-semibold flex items-center gap-2 active:scale-95 transition">
          <i data-lucide="plus" class="w-4 h-4"></i>
          <span>កត់ត្រាចំណាយថ្មី</span>
        </button>
      </div>
    `;
    if (window.lucide) window.lucide.createIcons();
    return;
  }

  if (expensesFilterState.viewTab === 'list') {
    listEl.innerHTML = items.map((item, idx) => `
      <div class="p-3 rounded-2xl bg-white/5 border border-white/5 flex flex-col gap-1.5 transition select-none shadow-sm">
        <div class="flex items-center justify-between">
          <div class="flex items-center gap-2 min-w-0 pr-2">
            <span class="w-6 h-6 rounded-full bg-rose-500/20 text-rose-400 font-mono font-bold text-xs flex items-center justify-center shrink-0">
              ${idx + 1}
            </span>
            <span class="font-bold text-xs text-white truncate">${item.description || item.category}</span>
          </div>
          <span class="font-mono text-rose-400 font-bold text-xs shrink-0 whitespace-nowrap">${formatUSD(item.amount)}</span>
        </div>
        <div class="text-[10px] text-slate-400 flex items-center justify-between pt-1 border-t border-white/5">
          <div class="flex items-center gap-2">
            <span>កាលបរិច្ឆេទ: <strong class="text-white">${item.date}</strong></span>
            ${item.time ? `<span class="text-amber-300 font-mono">⏰ ${item.time}</span>` : ''}
          </div>
          <span>ប្រភេទ: <strong class="text-slate-300">${item.category || 'ទូទៅ'}</strong></span>
        </div>
      </div>
    `).join('');
    if (window.lucide) window.lucide.createIcons();
    return;
  }

  // Telegram / iOS Storage Style Breakdown View
  renderExpensesBreakdownView(items, totalAmount, listEl);
}

function filterExpensesModalList() {
  const input = document.getElementById('expenses-modal-search-input');
  const clearBtn = document.getElementById('expenses-modal-clear-search');
  if (!input) return;
  const q = input.value.trim().toLowerCase();
  if (clearBtn) {
    if (q) clearBtn.classList.remove('hidden');
    else clearBtn.classList.add('hidden');
  }

  if (!q) {
    renderExpensesModalRows(currentLoadedExpenses);
    return;
  }

  const matched = currentLoadedExpenses.filter(e => {
    return (e.description && e.description.toLowerCase().includes(q)) ||
           (e.category && e.category.toLowerCase().includes(q)) ||
           (e.date && e.date.toLowerCase().includes(q)) ||
           (String(e.amount).includes(q));
  });

  renderExpensesModalRows(matched);
}

function clearExpensesModalSearch() {
  const input = document.getElementById('expenses-modal-search-input');
  const clearBtn = document.getElementById('expenses-modal-clear-search');
  if (input) {
    input.value = '';
    input.focus();
  }
  if (clearBtn) clearBtn.classList.add('hidden');
  renderExpensesModalRows(currentLoadedExpenses);
}

function closeExpensesModal() {
  closeAllExpensesDropdowns();
  const searchContainer = document.getElementById('expenses-modal-search-container');
  if (searchContainer) searchContainer.classList.add('hidden');
  const searchToggleBtn = document.getElementById('expenses-modal-search-toggle-btn');
  if (searchToggleBtn) {
    searchToggleBtn.classList.remove('bg-orange-500/20', 'text-white', 'border-orange-500/40');
    searchToggleBtn.classList.add('bg-white/5', 'text-orange-400', 'border-white/10');
  }
  const modal = document.getElementById('expenses-modal');
  if (modal) modal.classList.add('hidden');
  setDockVisible(true);
  if (window.navOpenedFromDrawer && window.navOpenedFromDrawer.expenses) {
    window.navOpenedFromDrawer.expenses = false;
    if (typeof openProfileDrawer === 'function') openProfileDrawer();
  }
}

