// Celestial Home Icon Glow Switcher (✨ -> ☀️ -> 🌙 Loop)
// ==========================================
let currentCelestialIndex = 0; // 0: ✨ sparkle, 1: ☀️ ray, 2: 🌙 moon
let lastHomeTapTime = 0;

function handleHomeClick(e) {
  const now = Date.now();
  const drawerModal = document.getElementById('profile-drawer-modal');
  const drawerPanel = document.getElementById('profile-drawer-panel');
  const isDrawerOpen = (drawerModal && !drawerModal.classList.contains('hidden')) || 
                       (drawerPanel && drawerPanel.classList.contains('translate-x-0'));

  const honorsModal = document.getElementById('honors-modal');
  const isHonorsOpen = honorsModal && !honorsModal.classList.contains('hidden');

  const tutorialModal = document.getElementById('tutorial-modal');
  const isTutorialOpen = tutorialModal && !tutorialModal.classList.contains('hidden');

  const openModal = document.querySelector('#sales-modal:not(.hidden), #expenses-modal:not(.hidden), #cod-modal:not(.hidden), #bank-modal:not(.hidden), #edit-bank-modal:not(.hidden), #payables-modal:not(.hidden), #team-sets-modal:not(.hidden), #all-customers-modal:not(.hidden), #team-members-modal:not(.hidden), #executive-hierarchy-modal:not(.hidden), #new-order-modal:not(.hidden), #new-expense-modal:not(.hidden), #global-search-modal:not(.hidden), #honors-modal:not(.hidden), #tutorial-modal:not(.hidden), #daily-report-modal:not(.hidden), #notif-modal:not(.hidden), #edit-profile-modal:not(.hidden), #change-pin-modal:not(.hidden), #about-modal:not(.hidden), #shortcut-modal:not(.hidden), #attendance-modal:not(.hidden), #member-daily-breakdown-modal:not(.hidden)');

  // Case 1: If Profile Drawer or any Modal is open ➔ Single tap smoothly dismisses it to reveal dashboard instantly (ZERO network reload)
  if (isDrawerOpen || openModal || isHonorsOpen || isTutorialOpen) {
    closeProfileDrawer();
    closeAllModals();
    const dock = document.getElementById('bottom-dock');
    if (dock) {
      dock.classList.remove('dock-hidden');
      dock.classList.remove('dock-profile-active');
    }
    if (appState.currentView !== 'dashboard') {
      switchView('dashboard', false);
    }
    if (navigator.vibrate) navigator.vibrate(10);
    return;
  }

  // Case 2: If currently on another tab (Analytics, Learning, Settings) ➔ Single tap switches to Dashboard instantly from memory (ZERO reload)
  if (appState.currentView !== 'dashboard') {
    switchView('dashboard', false);
    return;
  }

  // Case 3: Already on Dashboard ➔ Distinguish Single Tap (Scroll to Top) vs Double Tap (Reload Data)
  const timeDiff = now - lastHomeTapTime;
  lastHomeTapTime = now;

  if (timeDiff > 0 && timeDiff < 350) {
    // 👆👆 DOUBLE TAP (within 350ms): Manual Reload data from Google Sheet!
    lastHomeTapTime = 0; // reset
    if (navigator.vibrate) navigator.vibrate([15, 50, 15]);
    cycleHomeCelestialGlow();
    const main = document.getElementById('main-content');
    if (main) main.scrollTo({ top: 0, behavior: 'smooth' });
    manualReload();
  } else {
    // 👆 SINGLE TAP: Smooth scroll to top, cycle micro glow gently, instant reveal
    cycleHomeCelestialGlow();
    const main = document.getElementById('main-content');
    if (main) main.scrollTo({ top: 0, behavior: 'smooth' });
  }
}

