    if (raw) {
      const parsed = JSON.parse(raw);
      return {
        ...DEFAULT_OFFICE_CONFIG,
        ...parsed,
        allowedIps: Array.isArray(parsed.allowedIps) && parsed.allowedIps.length > 0 ? parsed.allowedIps : DEFAULT_OFFICE_CONFIG.allowedIps
      };
    }
