function getDailyMotivationQuote(type = 'ontime') {
  const d = new Date().getDate();
  if (type === 'checkout') return CHECKOUT_APPRECIATION_QUOTES[d % CHECKOUT_APPRECIATION_QUOTES.length];
  if (type === 'late') return LATE_EMPATHY_QUOTES[d % LATE_EMPATHY_QUOTES.length];
  return MORNING_ONTIME_QUOTES[d % MORNING_ONTIME_QUOTES.length];
}

function generateAttendanceTelegramText(actionType = null, extraNote = null) {
  const data = getAttendanceData();
  const p = (typeof getProfileData === 'function') ? getProfileData() : {};
  const now = new Date();

  // English month names
  const enMonths = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ];
  const day = now.getDate();
  const monthName = enMonths[now.getMonth()];
  const year = now.getFullYear();

  // Helper to format time into "hh:mm AM/PM" (e.g. 09:04 AM)
  const formatTime12 = (timeVal) => {
    if (!timeVal) return now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
    const m = String(timeVal).match(/(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?/i);
    if (m) {
      const hh = m[1].padStart(2, '0');
      const mm = m[2];
      const ampm = (m[3] || 'AM').toUpperCase();
      return `${hh}:${mm} ${ampm}`;
    }
    return timeVal;
  };

  // Determine English staff name
  let staffName = 'Chun Chanvicheka';
  if (p.nameEn && p.nameEn.trim()) {
    staffName = p.nameEn.trim();
  } else if (p.subtitle && /[A-Za-z]{3,}/.test(p.subtitle) && !p.subtitle.toLowerCase().includes('member')) {
    staffName = p.subtitle.trim();
  } else if (p.name && /^[A-Za-z\s]+$/.test(p.name.trim())) {
    staffName = p.name.trim();
  } else if (p.name) {
    if (typeof BOSTAR_TEAM_SELLERS !== 'undefined' && Array.isArray(BOSTAR_TEAM_SELLERS)) {
      const matchSeller = BOSTAR_TEAM_SELLERS.find(s => s && s.km && (s.km === p.name || p.name.includes(s.km)));
      if (matchSeller && matchSeller.en) {
        staffName = matchSeller.en;
      } else {
        staffName = p.name;
      }
    } else {
      staffName = p.name;
    }
  }

  // Determine Position
  let position = 'Sale Officer';
  if (p.position && p.position.trim()) {
    position = p.position.trim();
  } else if (p.work && /[A-Za-z]{3,}/.test(p.work) && !p.work.toLowerCase().includes('bostargroup')) {
    position = p.work.trim();
  } else {
    const core = (typeof getUserCoreRole === 'function') ? getUserCoreRole(p) : 'Member';
    if (core === 'Manager') position = 'Manager';
    else if (core === 'Leader') position = 'Team Leader';
    else position = 'Sale Officer';
  }

  // Determine Branch
  const branch = p.branch || 'BOSTAR GROUP';

  // Determine Manager
  let manager = p.manager || 'Bech Nora';
  if (!p.manager && typeof BOSTAR_MEMBERS_TEAM_MAP !== 'undefined' && Array.isArray(BOSTAR_MEMBERS_TEAM_MAP)) {
    const match = BOSTAR_MEMBERS_TEAM_MAP.find(m => m && (m.km === p.name || m.en === staffName));
    if (match && match.leader) {
      const lMatch = BOSTAR_MEMBERS_TEAM_MAP.find(m => m.km === match.leader || match.leader.includes(m.km));
      manager = (lMatch && lMatch.en) ? lMatch.en : match.leader.replace(/^លោក\s+/, '');
    }
  }
  if (!manager || manager === 'មិនទាន់បញ្ជាក់') manager = 'Bech Nora';

  const note = extraNote || data.note || '';
  const isCheckout = actionType === 'out' || (actionType === null && data.todayStatus === 'checked_out');
  const isLate = data.todayLate;

  // Checkout Format
  if (isCheckout) {
    const timeFormatted = formatTime12(data.checkOutTime || now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }));
    const dateTimeStr = `${day} ${monthName} ${year} ${timeFormatted}`;

    if (data.earlyCheckoutMinutes && data.earlyCheckoutMinutes > 0) {
      const earlyM = data.earlyCheckoutMinutes;
      const earlyDuration = earlyM >= 60 ? `${Math.floor(earlyM / 60)}h ${earlyM % 60}m` : `${earlyM}m`;
      const reasonText = note || 'Personal emergency';
      return `${staffName} checked out 🔴 Early ${earlyDuration}
Date Time: ${dateTimeStr}
Position: ${position}
Branch: ${branch}
Manager: ${manager}
Reason: ${reasonText}`;
    }

    return `${staffName} checked out 🔵 Good
Date Time: ${dateTimeStr}
Position: ${position}
Branch: ${branch}
Manager: ${manager}`;
  }

  // Checkin Format
  const inTimeStr = data.checkInTime || (data.todayStatus !== 'not_checked' ? '08:00 AM' : now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }));
  const timeFormatted = formatTime12(inTimeStr);
  const dateTimeStr = `${day} ${monthName} ${year} ${timeFormatted}`;

  if (isLate) {
    let lateDuration = '';
    const lateM = data.lateMinutes || 0;
    if (lateM >= 60) {
      const h = Math.floor(lateM / 60);
      const m = lateM % 60;
      lateDuration = m > 0 ? `${h}h ${m}m` : `${h}h`;
    } else if (lateM > 0) {
      lateDuration = `${lateM}m`;
    } else {
      lateDuration = '1h 4m';
    }

    const reasonText = note || 'Sorry I am late';
    return `${staffName} checked in 🔴 Late ${lateDuration}
Date Time: ${dateTimeStr}
Position: ${position}
Branch: ${branch}
Manager: ${manager}
Reason: ${reasonText}`;
  }

  // Early checkin
  if (data.earlyMinutes && data.earlyMinutes > 0) {
    const earlyM = data.earlyMinutes;
    const earlyDuration = earlyM >= 60 ? `${Math.floor(earlyM / 60)}h ${earlyM % 60}m` : `${earlyM}m`;
    return `${staffName} checked in 🟢 Early ${earlyDuration}
Date Time: ${dateTimeStr}
Position: ${position}
Branch: ${branch}
Manager: ${manager}`;
  }

  // On time
  return `${staffName} checked in 🟢 On time
Date Time: ${dateTimeStr}
Position: ${position}
Branch: ${branch}
Manager: ${manager}`;
}

async function copyAttendanceReportText(actionType = null) {
  const text = generateAttendanceTelegramText(actionType);
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
    } else {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }
    showToastNotification(appState.language === 'km' ? 'បានចម្លងវត្តមានជោគជ័យ! ត្រៀម Paste ចូល Telegram 📋' : 'Copied attendance! Ready to paste 📋');
  } catch (_) {
    showToastNotification('ចម្លងបានជោគជ័យ!');
  }
}

async function shareAttendanceToTelegram(actionType = null) {
  const text = generateAttendanceTelegramText(actionType);
  copyAttendanceReportText(actionType);
  
  showToastNotification('កំពុងបញ្ជូនវត្តមានទៅកាន់ Telegram... ⏳');
  
  const botSuccess = await sendAttendanceViaTelegramBot(text);
  if (botSuccess) {
    showToastNotification('បានផ្ញើវត្តមានចូល Telegram Group ស្វ័យប្រវត្តិជោគជ័យ! 🚀');
    if (navigator.vibrate) try { navigator.vibrate([40, 60, 40]); } catch(_) {}
  } else {
    // Fallback: open group link if bot API network is blocked
    const savedGroup = getTelegramGroupUrl();
    if (savedGroup && savedGroup.startsWith('http')) {
      window.open(savedGroup, '_blank');
    }
  }
}

function toggleAttendanceAutoShare() {
  const current = localStorage.getItem('sd_attendance_autoshare') !== 'false';
  const nextVal = !current;
  localStorage.setItem('sd_attendance_autoshare', nextVal ? 'true' : 'false');
  showToastNotification(nextVal ? 'បានបើកការផ្ញើទៅ Telegram ស្វ័យប្រវត្តិ 🚀' : 'បានបិទការផ្ញើទៅ Telegram ស្វ័យប្រវត្តិ');
  renderAttendanceContent();
}

function quickSetAttendanceTime(inputId, val) {
  const input = document.getElementById(inputId);
  if (!input) return;
  if (val === 'now') {
    const now = new Date();
    input.value = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
  } else {
    input.value = val;
  }
}

function quickSetAttendanceLocation(locName) {
  const input = document.getElementById('att-edit-location');
  if (input) input.value = locName;
}

function openAttendanceEditModal() {
  const modal = document.getElementById('attendance-edit-modal');
  if (!modal) return;
  renderAttendanceEditForm();
  modal.classList.remove('hidden');
  if (window.lucide) window.lucide.createIcons();
}

function closeAttendanceEditModal() {
  const modal = document.getElementById('attendance-edit-modal');
  if (!modal) return;
  modal.classList.add('hidden');
}

