function saveAttendanceEditForm(andShare = false) {
  const data = getAttendanceData();
  const selectedStatusEl = document.querySelector('input[name="att_status"]:checked');
  const inTimeInput = document.getElementById('att-edit-in-time');
  const outTimeInput = document.getElementById('att-edit-out-time');
  const isLateEl = document.getElementById('att-edit-is-late');
  const locInput = document.getElementById('att-edit-location');
  const noteInput = document.getElementById('att-edit-note');
  const tgGroupInput = document.getElementById('att-edit-tg-group');

  if (selectedStatusEl) data.todayStatus = selectedStatusEl.value;
  if (inTimeInput) data.checkInTime = inTimeInput.value.trim() || null;
  if (outTimeInput) data.checkOutTime = outTimeInput.value.trim() || null;
  if (isLateEl) data.todayLate = isLateEl.checked;
  if (locInput) data.location = locInput.value.trim() || 'ការិយាល័យកណ្តាល (HQ)';
  if (noteInput) data.note = noteInput.value.trim();

  if (data.todayStatus === 'checked_out' && data.checkInTime && data.checkOutTime) {
    data.duration = calculateAttendanceDuration(data.checkInTime, data.checkOutTime);
  }

  // Update records for today
  const now = new Date();
  const today = now.getDate();
  const existingIdx = (data.records || []).findIndex(r => r.day === today);
  const newRecord = {
    day: today,
    date: `${String(today).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`,
    checkIn: data.checkInTime || '08:00 AM',
    checkOut: data.checkOutTime || '—',
    status: data.todayStatus === 'leave' ? 'leave' : (data.todayLate ? 'late' : 'present'),
    duration: data.duration || '—'
  };
  if (existingIdx >= 0) {
    data.records[existingIdx] = newRecord;
  } else {
    data.records.push(newRecord);
  }

  // Save TG bot token, chat id, and group if changed (Attendance scope)
  const tgTokenInput = document.getElementById('att-edit-tg-token');
  const tgChatIdInput = document.getElementById('att-edit-tg-chat-id');
  if (tgTokenInput) localStorage.setItem('sd_telegram_bot_token', tgTokenInput.value.trim());
  if (tgChatIdInput) {
    const val = tgChatIdInput.value.trim();
    localStorage.setItem('sd_attendance_tg_chat_id', val);
    localStorage.setItem('sd_telegram_chat_id', val);
  }
  if (tgGroupInput) {
    const val = tgGroupInput.value.trim();
    localStorage.setItem('sd_attendance_tg_group_url', val);
    localStorage.setItem('sd_telegram_group_url', val);
  }

  // Save Office Verification Config
  const cfgEnabled = document.getElementById('att-cfg-enabled');
  const cfgIps = document.getElementById('att-cfg-allowed-ips');
  const cfgLat = document.getElementById('att-cfg-lat');
  const cfgLon = document.getElementById('att-cfg-lon');
  const cfgRad = document.getElementById('att-cfg-radius');
  if (cfgIps) {
    const rawIps = cfgIps.value.split(',').map(s => s.trim()).filter(Boolean);
    const cfg = {
      enabled: cfgEnabled ? cfgEnabled.checked : true,
      allowedIps: rawIps.length > 0 ? rawIps : ['45.119.135.224'],
      latitude: Number(cfgLat?.value) || 11.5362769,
      longitude: Number(cfgLon?.value) || 104.8865537,
      radiusMeters: Number(cfgRad?.value) || 150
    };
    saveOfficeConfig(cfg);
  }

  saveAttendanceData(data);
  closeAttendanceEditModal();
  renderAttendanceContent();
  renderProfileDrawerContent();

  showToastNotification('បាន Update វត្តមានជោគជ័យ! ✅');

  if (andShare) {
    setTimeout(() => {
      shareAttendanceToTelegram();
    }, 300);
  }
}

let attendanceScrollInitialized = false;
function setupAttendanceScroll() {
  const scrollEl = document.getElementById('attendance-modal-body');
  if (!scrollEl || attendanceScrollInitialized) return;
  attendanceScrollInitialized = true;

  let lastScrollTop = scrollEl.scrollTop || 0;
  let dockIdleTimer = null;

  scrollEl.addEventListener('scroll', () => {
    const currentScrollTop = scrollEl.scrollTop;
    const diff = currentScrollTop - lastScrollTop;

    // 1. Scrolling down into deeper items (finger dragging up) -> Smoothly hide Dock
    if (diff > 8 && currentScrollTop > 30) {
      setDockVisible(false);
    }
    // 2. Scrolling back up towards top (finger dragging down) OR near top -> Immediately restore Dock
    else if (diff < -5 || currentScrollTop <= 15) {
      setDockVisible(true);
    }

    lastScrollTop = currentScrollTop;
    // 3. When scrolling stops / screen is still -> Smoothly restore Dock
    clearTimeout(dockIdleTimer);
    dockIdleTimer = setTimeout(() => {
      setDockVisible(true);
    }, 450);
  }, { passive: true });
}

function openAttendanceModal(fromDrawer = false) {
  if (!window.navOpenedFromDrawer) window.navOpenedFromDrawer = {};
  window.navOpenedFromDrawer.attendance = !!fromDrawer;
  const modal = document.getElementById('attendance-modal');
  if (!modal) return;
  renderAttendanceContent();
  modal.classList.remove('hidden');

  // Keep dock visible and smoothly hook for auto-hide on scroll (like All Customers)
  setDockVisible(true);
  const scrollEl = document.getElementById('attendance-modal-body');
  if (scrollEl) {
    scrollEl.scrollTop = 0;
  }
  setupAttendanceScroll();

  if (window._attendanceClockInterval) clearInterval(window._attendanceClockInterval);
  window._attendanceClockInterval = setInterval(updateAttendanceLiveClock, 1000);

  if (window.lucide) window.lucide.createIcons();
  if (navigator.vibrate) try { navigator.vibrate(15); } catch(_) {}
}

function closeAttendanceModal() {
  const modal = document.getElementById('attendance-modal');
  if (!modal) return;
  modal.classList.add('hidden');
  if (window._attendanceClockInterval) {
    clearInterval(window._attendanceClockInterval);
    window._attendanceClockInterval = null;
  }
  setDockVisible(true);
  if (window.navOpenedFromDrawer && window.navOpenedFromDrawer.attendance) {
    window.navOpenedFromDrawer.attendance = false;
    if (typeof openProfileDrawer === 'function') openProfileDrawer();
  }
  if (navigator.vibrate) try { navigator.vibrate(12); } catch(_) {}
}


