function openAttendanceLeaveModal() {
  const modal = document.getElementById('attendance-leave-modal');
  if (!modal) return;

  const p = (typeof getProfileData === 'function') ? getProfileData() : {};
  const cleanId = String(p.memberId || 'BG-001').replace(/^(ID:\s*)+/i, '').trim();
  const coreRole = (typeof getUserCoreRole === 'function') ? getUserCoreRole(p) : 'Member';

  const applicantNameEl = document.getElementById('att-leave-applicant-name');
  const applicantIdEl = document.getElementById('att-leave-applicant-id');
  if (applicantNameEl) applicantNameEl.textContent = p.name || 'ក្រុមការងារ';
  if (applicantIdEl) applicantIdEl.textContent = cleanId ? `ID: ${cleanId}` : 'ID: BG-001';

  const roleBadgeEl = document.getElementById('att-leave-applicant-role-badge');
  if (roleBadgeEl && typeof getUserCoreRoleBadge === 'function') {
    roleBadgeEl.innerHTML = getUserCoreRoleBadge(coreRole);
  }
  const avatarImgEl = document.getElementById('att-leave-applicant-img');
  if (avatarImgEl) {
    avatarImgEl.src = p.avatar || 'bostar-logo.png';
  }

  // Populate leader select with 6 core Bostar Team Leaders / Managers
  const leaderSelect = document.getElementById('att-leave-leader-select');
  if (leaderSelect) {
    leaderSelect.innerHTML = BOSTAR_CORE_LEADERS.map((key, index) => {
      const displayName = getLeaderDisplayName(key);
      const isSelected = key === 'Bech_Nora' ? 'selected' : (key === 'Sdey_Sdoeung' ? '' : '');
      return `<option value="${key}" ${isSelected}>${index + 1}. ${displayName}</option>`;
    }).join('');
  }

  // Set default dates
  const today = new Date().toISOString().split('T')[0];
  const startDateInput = document.getElementById('att-leave-start-date');
  const endDateInput = document.getElementById('att-leave-end-date');
  if (startDateInput) startDateInput.value = today;
  if (endDateInput) endDateInput.value = today;

  selectLeaveDurationType('full_day');

  const reasonInput = document.getElementById('att-leave-reason-input');
  if (reasonInput) reasonInput.value = '';

  modal.classList.remove('hidden');
  setDockVisible(true);
  const scrollEl = document.getElementById('attendance-leave-body');
  if (scrollEl) {
    scrollEl.scrollTop = 0;
    if (typeof hookScrollableForDock === 'function') {
      hookScrollableForDock(scrollEl, false);
    }
  }
  if (window.lucide) window.lucide.createIcons();
}

function closeAttendanceLeaveModal() {
  const modal = document.getElementById('attendance-leave-modal');
  if (modal) modal.classList.add('hidden');
  setDockVisible(true);
}

function selectLeaveDurationType(type) {
  const hidden = document.getElementById('att-leave-duration-type');
  if (hidden) hidden.value = type;

  document.querySelectorAll('.leave-dur-pill').forEach(btn => {
    btn.className = 'leave-dur-pill px-2 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-300 text-[11px] font-medium transition';
  });
  const activeBtn = document.getElementById('leave-dur-btn-' + type);
  if (activeBtn) {
    activeBtn.className = 'leave-dur-pill px-2 py-2 rounded-xl bg-blue-500/20 border border-blue-500/50 text-blue-300 text-[11px] font-bold transition';
  }

  const endWrapper = document.getElementById('att-leave-end-date-wrapper');
  if (endWrapper) {
    if (type === 'multi_days') {
      endWrapper.classList.remove('hidden');
    } else {
      endWrapper.classList.add('hidden');
      const startInput = document.getElementById('att-leave-start-date');
      const endInput = document.getElementById('att-leave-end-date');
      if (startInput && endInput) endInput.value = startInput.value;
    }
  }
}

function selectLeaveReasonChip(text) {
  const input = document.getElementById('att-leave-reason-input');
  if (input) input.value = text;
}

function getEnglishStaffName(p) {
  p = p || (typeof getProfileData === 'function' ? getProfileData() : {});
  if (p.nameEn && p.nameEn.trim()) return p.nameEn.trim();
  if (p.subtitle && /[A-Za-z]{3,}/.test(p.subtitle) && !p.subtitle.toLowerCase().includes('member')) return p.subtitle.trim();
  if (p.name && /^[A-Za-z\s]+$/.test(p.name.trim())) return p.name.trim();
  if (p.name && typeof BOSTAR_TEAM_SELLERS !== 'undefined' && Array.isArray(BOSTAR_TEAM_SELLERS)) {
    const match = BOSTAR_TEAM_SELLERS.find(s => s && s.km && (s.km === p.name || p.name.includes(s.km)));
    if (match && match.en) return match.en;
  }
  return p.name || 'Sab Leakhena';
}
window.getEnglishStaffName = getEnglishStaffName;

function getEnglishLeaderName(leaderKeyOrName) {
  if (!leaderKeyOrName) return 'Bech Nora';
  const raw = String(leaderKeyOrName);
  if (raw.includes('Nora') || raw.includes('នោរ៉ា')) return 'Bech Nora';
  if (raw.includes('Sdey') || raw.includes('Sdoeung') || raw.includes('ស្ដី')) return 'Sdey Sdoeung';
  if (raw.includes('Udom') || raw.includes('ឧត្តម')) return 'Bech Udom';
  if (raw.includes('Leanghak') || raw.includes('លាងហាក់')) return 'Sroeun Leanghak';
  if (raw.includes('Chanthy') || raw.includes('ចន្ធី')) return 'Hem Chanthy';
  if (raw.includes('Yaith') || raw.includes('យ៉ារិទ្ធ')) return 'Hour Yaith';
  return raw.replace(/^លោក\s+/, '').replace(/_/g, ' ');
}
window.getEnglishLeaderName = getEnglishLeaderName;

function generateLeaveTelegramText(req, statusOverride = null) {
  const status = statusOverride || req.status || 'pending';
  const staffName = getEnglishStaffName({ name: req.staffName, memberId: req.staffId });
  const managerName = getEnglishLeaderName(req.approvedBy || req.leaderName || req.leaderKey || 'Bech Nora');

  // Request Date formatting: e.g. "Mon 26 Oct 2026 | Full Day"
  const sDate = req.startDate ? new Date(req.startDate) : new Date();
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  
  let dateFormatted = `${dayNames[sDate.getDay()]} ${sDate.getDate()} ${monthNames[sDate.getMonth()]} ${sDate.getFullYear()}`;
  if (req.endDate && req.endDate !== req.startDate) {
    const eDate = new Date(req.endDate);
    dateFormatted = `${dayNames[sDate.getDay()]} ${sDate.getDate()} ${monthNames[sDate.getMonth()]} - ${dayNames[eDate.getDay()]} ${eDate.getDate()} ${monthNames[eDate.getMonth()]} ${eDate.getFullYear()}`;
  }

  // Duration & Amount
  let shiftLabel = 'Full Day';
  let amountText = '1 day';
  const durRaw = (req.duration || '').toLowerCase();
  if (durRaw.includes('morning') || durRaw.includes('ព្រឹក')) {
    shiftLabel = 'Morning';
    amountText = '0.5 day';
  } else if (durRaw.includes('afternoon') || durRaw.includes('រសៀល')) {
    shiftLabel = 'Afternoon';
    amountText = '0.5 day';
  } else if (durRaw.includes('multi') || (req.endDate && req.endDate !== req.startDate)) {
    shiftLabel = 'Multiple Days';
    const sTime = new Date(req.startDate).getTime();
    const eTime = new Date(req.endDate).getTime();
    const days = Math.max(1, Math.round((eTime - sTime) / (1000 * 60 * 60 * 24)) + 1);
    amountText = `${days} days`;
  }

  const reason = req.reason || '';

  if (status === 'approved') {
    return `✉️ ${staffName}Leave Request🟢Approved
Request Date: ${dateFormatted} | ${shiftLabel}
Amount: ${amountText}
Approval By: ${managerName}
Reason: ${reason}
${managerName} 🟢Approved`;
  }

  if (status === 'rejected') {
    return `✉️ ${staffName}Leave Request🔴Rejected
Request Date: ${dateFormatted} | ${shiftLabel}
Amount: ${amountText}
Rejected By: ${managerName}
Reason: ${reason}
${managerName} 🔴Rejected`;
  }

  // Pending
  return `✉️ ${staffName}Leave Request🟡Pending
Request Date: ${dateFormatted} | ${shiftLabel}
Amount: ${amountText}
Approval By: ${managerName}
Reason: ${reason}`;
}
window.generateLeaveTelegramText = generateLeaveTelegramText;

async function submitAttendanceLeaveRequest() {
  const p = (typeof getProfileData === 'function') ? getProfileData() : {};
  const applicantName = p.name || 'ក្រុមការងារ';
  const cleanId = String(p.memberId || 'BG-001').replace(/^(ID:\s*)+/i, '').trim();
  const applicantId = cleanId ? `ID: ${cleanId}` : 'ID: BG-001';
  const coreRole = (typeof getUserCoreRole === 'function') ? getUserCoreRole(p) : 'Member';

  const typeRadio = document.querySelector('input[name="att_leave_type"]:checked');
  const leaveType = typeRadio ? typeRadio.value : 'ច្បាប់ឈឺ (Sick Leave)';

  const durType = document.getElementById('att-leave-duration-type')?.value || 'full_day';
  const startDate = document.getElementById('att-leave-start-date')?.value || new Date().toISOString().split('T')[0];
  const endDate = durType === 'multi_days' ? (document.getElementById('att-leave-end-date')?.value || startDate) : startDate;

  const leaderKey = document.getElementById('att-leave-leader-select')?.value || 'Bech_Nora';
  const leaderName = getLeaderDisplayName(leaderKey);

  const reasonInput = document.getElementById('att-leave-reason-input');
  const reason = reasonInput ? reasonInput.value.trim() : '';

  if (!reason) {
    showToastNotification('សូមបញ្ជាក់មូលហេតុនៃការសុំច្បាប់! ✍️');
    if (reasonInput) reasonInput.focus();
    return;
  }

  const durLabels = {
    full_day: 'ពេញមួយថ្ងៃ (Full Day)',
    morning: 'កន្លះថ្ងៃ - ព្រឹក (Morning 08:00 - 12:00)',
    afternoon: 'កន្លះថ្ងៃ - រសៀល (Afternoon 01:30 - 05:00)',
    multi_days: 'ច្រើនថ្ងៃ (Multiple Days)'
  };
  const durationText = durLabels[durType] || durType;
  const dateRangeText = (startDate === endDate) ? startDate : `${startDate} ដល់ ${endDate}`;

  const newReq = {
    id: 'LEAVE_' + Date.now(),
    staffName: applicantName,
    staffId: applicantId,
    role: coreRole,
    leaveType: leaveType,
    duration: durationText,
    startDate: startDate,
    endDate: endDate,
    leaderKey: leaderKey,
    leaderName: leaderName,
    reason: reason,
    status: 'pending',
    createdAt: new Date().toLocaleString('en-US', { hour: '2-digit', minute: '2-digit', month: '2-digit', day: '2-digit', year: 'numeric' })
  };

  const list = getLeaveRequests();
  list.unshift(newReq);
  saveLeaveRequests(list);

  // Send Telegram Notification via bot
  const tgText = generateLeaveTelegramText(newReq, 'pending');

  try {
    await sendAttendanceViaTelegramBot(tgText);
  } catch (err) {
    console.warn('Telegram notify error:', err);
  }

  closeAttendanceLeaveModal();
  renderAttendanceContent();
  showToastNotification('ពាក្យសុំច្បាប់ត្រូវបានបញ្ជូនទៅ Manager/Leader តាម Telegram រួចរាល់! 📩');
  if (navigator.vibrate) try { navigator.vibrate([20, 60, 20]); } catch(_) {}
}

