function submitUserFeedback() {
  const input = document.getElementById('feedback-text-input');
  const val = input ? input.value.trim() : '';
  if (!val) {
    showToastNotification('សូមសរសេរមតិយោបល់មុននឹងផ្ញើ!');
    return;
  }
  showToastNotification('អរគុណច្រើនសម្រាប់មតិយោបល់របស់អ្នក! 🙏');
  if (input) input.value = '';
  closeProfileSubModal();
}
window.submitUserFeedback = submitUserFeedback;

// ========================================================
// INTEGRATED TWO-HAND 3D RULER WHEEL & DAILY REPORT ENGINE
// Left Hand Taps Field to Select | Right Hand Swipes Ruler to Adjust
// ========================================================
let _rulerState = {
  targetFieldId: 'rep-field-chat-target',
  title: 'ឆាតគោលដៅ',
  min: 0,
  max: 500,
  unit: 'នាក់',
  val: 0,
  pixelOffset: 0,
  isDragging: false,
  startX: 0,
  startOffset: 0,
  tickSpacing: 14,
  animFrameId: null,
  lastVibrateVal: null
};

let _stepTimer = null;
let _stepInterval = null;

function changeReportFieldVal(fieldId, delta) {
  const input = document.getElementById(fieldId);
  if (!input) return;
  let val = (Number(input.value) || 0) + delta;
  if (val < 0) val = 0;
  input.value = val;

  // Subtle highlight card when clicked
  const card = document.getElementById(`card-${fieldId}`);
  if (card) {
    card.classList.add('border-amber-400/80', 'bg-amber-500/10');
    setTimeout(() => {
      if (card) card.classList.remove('border-amber-400/80', 'bg-amber-500/10');
    }, 200);
  }

  calculateDailyReportMetrics();
  if (navigator.vibrate) try { navigator.vibrate(8); } catch (_) {}
}

function onReportFieldManualInput(fieldId) {
  const input = document.getElementById(fieldId);
  if (!input) return;
  let clean = input.value.replace(/[^0-9]/g, '');
  if (clean === '') clean = '0';
  const val = parseInt(clean, 10) || 0;
  input.value = val;

  calculateDailyReportMetrics();
}
window.onReportFieldManualInput = onReportFieldManualInput;

function stepFieldPress(fieldId, delta, ev) {
  if (ev) ev.stopPropagation();
  changeReportFieldVal(fieldId, delta);

  clearTimeout(_stepTimer);
  clearInterval(_stepInterval);
  _stepTimer = setTimeout(() => {
    _stepInterval = setInterval(() => {
      changeReportFieldVal(fieldId, delta);
    }, 110);
  }, 350);
}

function stepFieldRelease(ev) {
  if (ev) ev.stopPropagation();
  clearTimeout(_stepTimer);
  clearInterval(_stepInterval);
  _stepTimer = null;
  _stepInterval = null;
}

window.changeReportFieldVal = changeReportFieldVal;
window.stepFieldPress = stepFieldPress;
window.stepFieldRelease = stepFieldRelease;

function renderRulerNumberControl(id, label, defaultVal, unit, min, max, fieldTitleKm) {
  const v = Number(defaultVal) || 0;
  return `
    <div id="card-${id}"
         class="report-field-item p-2 sm:p-2.5 rounded-2xl bg-[#0B1528] border border-white/10 hover:border-amber-500/40 transition select-none flex flex-col justify-between group shadow-sm">
      <div class="flex items-center justify-between mb-1.5 min-w-0">
        <span class="text-xs text-slate-200 font-bold truncate group-hover:text-amber-400 transition">${label}</span>
        <span class="text-[10px] text-slate-400 font-kantumruy font-semibold shrink-0 ml-1">${unit}</span>
      </div>

      <!-- Compact Standard Stepper: [-] [ Num Key Input ] [+] -->
      <div class="flex items-center justify-between bg-black/60 px-1 py-1 rounded-xl border border-white/10 gap-1">
        <!-- Minus Button on Left -->
        <button type="button" 
                onpointerdown="stepFieldPress('${id}', -1, event)"
                onpointerup="stepFieldRelease(event)"
                onpointerleave="stepFieldRelease(event)"
                onpointercancel="stepFieldRelease(event)"
                onclick="event.stopPropagation();"
                class="w-7 h-7 sm:w-8 sm:h-8 rounded-lg bg-white/10 hover:bg-white/20 active:bg-amber-500 active:text-black text-white font-black text-lg flex items-center justify-center transition active:scale-90 shrink-0 select-none shadow-sm touch-manipulation"
                title="បន្ថយ">
          −
        </button>

        <!-- Center Number Display (Interactive Numeric Keypad Input!) -->
        <div class="flex-1 text-center min-w-0 px-1">
          <input type="text"
                 inputmode="numeric"
                 pattern="[0-9]*"
                 id="${id}"
                 value="${v}"
                 onclick="this.select();"
                 onfocus="this.select();"
                 oninput="onReportFieldManualInput('${id}')"
                 class="w-full bg-transparent text-center text-base sm:text-lg font-mono font-black text-amber-400 focus:outline-none focus:text-amber-300 selection:bg-amber-500/30 p-0 m-0 border-none leading-tight drop-shadow-sm cursor-text"
                 style="font-size: 17px !important; -webkit-user-select: text !important; user-select: text !important;">
        </div>

        <!-- Plus Button on Right -->
        <button type="button" 
                onpointerdown="stepFieldPress('${id}', 1, event)"
                onpointerup="stepFieldRelease(event)"
                onpointerleave="stepFieldRelease(event)"
                onpointercancel="stepFieldRelease(event)"
                onclick="event.stopPropagation();"
                class="w-7 h-7 sm:w-8 sm:h-8 rounded-lg bg-white/10 hover:bg-white/20 active:bg-amber-500 active:text-black text-white font-black text-lg flex items-center justify-center transition active:scale-90 shrink-0 select-none shadow-sm touch-manipulation"
                title="បន្ថែម">
          +
        </button>
      </div>
    </div>
  `;
}

