let miniCalMonth = 9; // 0-indexed (9 = October)
let miniCalSelectedDay = 15;

const MONTH_NAMES_EN = [
  'OCTOBER', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE',
  'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'
];

function updateOrderDateDisplay(isoDate) {
  if (!isoDate) {
    const now = new Date();
    isoDate = typeof getLocalIsoDate === 'function' ? getLocalIsoDate(now) : now.toISOString().slice(0, 10);
  }
  let ddmmyyyy = isoDate;
  const parts = String(isoDate).split('-');
  if (parts.length === 3) {
    ddmmyyyy = `${parts[2]}/${parts[1]}/${parts[0]}`;
    miniCalYear = parseInt(parts[0], 10);
    miniCalMonth = parseInt(parts[1], 10) - 1;
    miniCalSelectedDay = parseInt(parts[2], 10);
  }
  const textInput = document.getElementById('order-field-date-text');
  if (textInput) textInput.value = ddmmyyyy;
  const hiddenInp = document.getElementById('order-field-date');
  if (hiddenInp) hiddenInp.value = isoDate;
}

function onOrderDateTextInput(val) {
  const raw = (val || '').trim();
  const ddmmyyyy = raw.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})/);
  if (ddmmyyyy) {
    const dy = ddmmyyyy[1].padStart(2, '0');
    const mo = ddmmyyyy[2].padStart(2, '0');
    const yr = ddmmyyyy[3];
    const iso = `${yr}-${mo}-${dy}`;
    const hiddenInp = document.getElementById('order-field-date');
    if (hiddenInp) hiddenInp.value = iso;
    miniCalSelectedDay = parseInt(dy, 10);
    miniCalMonth = parseInt(mo, 10) - 1;
    miniCalYear = parseInt(yr, 10);
  }
}

function toggleOrderMiniCalendar(e) {
  if (e) {
    e.stopPropagation();
    e.preventDefault();
  }
  const popup = document.getElementById('order-mini-calendar-popup');
  if (!popup) return;
  const isHidden = popup.classList.contains('hidden');
  if (isHidden) {
    syncMiniCalDateFromInput();
    renderOrderMiniCalendar();
    popup.classList.remove('hidden');
    setTimeout(() => {
      document.addEventListener('click', closeMiniCalendarOnClickOutside);
    }, 10);
  } else {
    popup.classList.add('hidden');
    document.removeEventListener('click', closeMiniCalendarOnClickOutside);
  }
}

function closeMiniCalendarOnClickOutside(e) {
  const popup = document.getElementById('order-mini-calendar-popup');
  const btn = document.getElementById('btn-toggle-mini-calendar');
  const inp = document.getElementById('order-field-date-text');
  if (popup && !popup.contains(e.target) && btn && !btn.contains(e.target) && inp && !inp.contains(e.target)) {
    popup.classList.add('hidden');
    document.removeEventListener('click', closeMiniCalendarOnClickOutside);
  }
}

function syncMiniCalDateFromInput() {
  const textInput = document.getElementById('order-field-date-text');
  const raw = (textInput?.value || '').trim();
  const ddmmyyyy = raw.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})/);
  if (ddmmyyyy) {
    miniCalSelectedDay = parseInt(ddmmyyyy[1], 10);
    miniCalMonth = parseInt(ddmmyyyy[2], 10) - 1;
    miniCalYear = parseInt(ddmmyyyy[3], 10);
  } else {
    const hiddenInp = document.getElementById('order-field-date');
    if (hiddenInp && /^\d{4}-\d{2}-\d{2}$/.test(hiddenInp.value)) {
      const p = hiddenInp.value.split('-');
      miniCalYear = parseInt(p[0], 10);
      miniCalMonth = parseInt(p[1], 10) - 1;
      miniCalSelectedDay = parseInt(p[2], 10);
    }
  }
}

function changeMiniCalMonth(delta, e) {
  if (e) e.stopPropagation();
  miniCalMonth += delta;
  if (miniCalMonth < 0) {
    miniCalMonth = 11;
    miniCalYear -= 1;
  } else if (miniCalMonth > 11) {
    miniCalMonth = 0;
    miniCalYear += 1;
  }
  renderOrderMiniCalendar();
}

function selectMiniCalToday(e) {
  if (e) e.stopPropagation();
  const now = new Date();
  miniCalYear = now.getFullYear();
  miniCalMonth = now.getMonth();
  selectMiniCalDay(now.getDate(), e);
}

function selectMiniCalYesterday(e) {
  if (e) e.stopPropagation();
  const y = new Date();
  y.setDate(y.getDate() - 1);
  miniCalYear = y.getFullYear();
  miniCalMonth = y.getMonth();
  selectMiniCalDay(y.getDate(), e);
}

function selectMiniCalDay(day, e) {
  if (e) e.stopPropagation();
  miniCalSelectedDay = day;

  const dy = String(day).padStart(2, '0');
  const mo = String(miniCalMonth + 1).padStart(2, '0');
  const yr = miniCalYear;
  const ddmmyyyy = `${dy}/${mo}/${yr}`;
  const iso = `${yr}-${mo}-${dy}`;

  const textInput = document.getElementById('order-field-date-text');
  if (textInput) textInput.value = ddmmyyyy;

  const hiddenInp = document.getElementById('order-field-date');
  if (hiddenInp) hiddenInp.value = iso;

  renderOrderMiniCalendar();

  setTimeout(() => {
    const popup = document.getElementById('order-mini-calendar-popup');
    if (popup) popup.classList.add('hidden');
    document.removeEventListener('click', closeMiniCalendarOnClickOutside);
  }, 120);

  if (navigator.vibrate) try { navigator.vibrate(10); } catch (_) {}
}

function renderOrderMiniCalendar() {
  const popup = document.getElementById('order-mini-calendar-popup');
  if (!popup) return;

  const khmerMonths = [
    'មករា', 'កុម្ភៈ', 'មីនា', 'មេសា', 'ឧសភា', 'មិថុនា',
    'កក្កដា', 'សីហា', 'កញ្ញា', 'តុលា', 'វិច្ឆិកា', 'ធ្នូ'
  ];
  const monthTitle = `${khmerMonths[miniCalMonth] || 'តុលា'} ${miniCalYear}`;
  const firstDay = new Date(miniCalYear, miniCalMonth, 1).getDay(); // 0 = Sun
  const daysInMonth = new Date(miniCalYear, miniCalMonth + 1, 0).getDate();

  const now = new Date();
  const isCurrentYearMonth = (now.getFullYear() === miniCalYear && now.getMonth() === miniCalMonth);
  const realTodayDate = now.getDate();

  const yest = new Date();
  yest.setDate(yest.getDate() - 1);
  const isYesterdayYearMonth = (yest.getFullYear() === miniCalYear && yest.getMonth() === miniCalMonth);
  const realYesterdayDate = yest.getDate();

  const isTodaySelected = isCurrentYearMonth && (miniCalSelectedDay === realTodayDate);
  const isYesterdaySelected = isYesterdayYearMonth && (miniCalSelectedDay === realYesterdayDate);

  let html = `
    <!-- Header with Khmer Month Title and Navigation -->
    <div class="flex items-center justify-between mb-2.5 pb-2 border-b border-white/10">
      <button type="button" onclick="changeMiniCalMonth(-1, event)" class="w-7 h-7 rounded-full bg-white/5 hover:bg-white/15 active:scale-90 text-slate-300 hover:text-white flex items-center justify-center text-sm font-bold transition">‹</button>
      <span class="text-xs font-bold tracking-wide text-orange-400 font-kantumruy">
        ${monthTitle}
      </span>
      <button type="button" onclick="changeMiniCalMonth(1, event)" class="w-7 h-7 rounded-full bg-white/5 hover:bg-white/15 active:scale-90 text-slate-300 hover:text-white flex items-center justify-center text-sm font-bold transition">›</button>
    </div>

    <!-- Quick Shortcuts (Today / Yesterday) -->
    <div class="grid grid-cols-2 gap-1.5 mb-2.5 pb-2 border-b border-white/10">
      <button type="button" onclick="selectMiniCalToday(event)" 
              class="py-1 px-2 rounded-xl text-center text-[11px] font-semibold font-kantumruy transition active:scale-95 ${isTodaySelected ? 'bg-orange-500 text-white font-bold shadow-sm' : 'bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10'}">
        ☀️ ថ្ងៃនេះ
      </button>
      <button type="button" onclick="selectMiniCalYesterday(event)" 
              class="py-1 px-2 rounded-xl text-center text-[11px] font-semibold font-kantumruy transition active:scale-95 ${isYesterdaySelected ? 'bg-orange-500 text-white font-bold shadow-sm' : 'bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10'}">
        ⏮️ ម្សិលមិញ
      </button>
    </div>

    <!-- Day Headers: អា ច អ ពុ ព្រ សុ ស -->
    <div class="grid grid-cols-7 text-center mb-1 text-[11px] font-bold text-slate-400 font-kantumruy">
      <span>អា</span><span>ច</span><span>អ</span><span>ពុ</span><span>ព្រ</span><span>សុ</span><span>ស</span>
    </div>

    <!-- Days Grid -->
    <div class="grid grid-cols-7 gap-y-1 text-center font-sans text-xs">
  `;

  // Empty leading slots
  for (let i = 0; i < firstDay; i++) {
    html += `<div class="h-8"></div>`;
  }

  // Days in month
  for (let d = 1; d <= daysInMonth; d++) {
    const isSelected = (d === miniCalSelectedDay);
    const isToday = isCurrentYearMonth && (d === realTodayDate);

    let cellClasses = 'w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold cursor-pointer active:scale-90 transition ';
    if (isSelected) {
      cellClasses += 'bg-orange-500 text-white font-bold shadow-md shadow-orange-500/30';
    } else if (isToday) {
      cellClasses += 'border border-orange-500/60 text-orange-400 hover:bg-orange-500/20';
    } else {
      cellClasses += 'text-slate-200 hover:bg-white/10';
    }

    html += `
      <div class="flex items-center justify-center py-0.5">
        <button type="button" onclick="selectMiniCalDay(${d}, event)" 
                class="${cellClasses}">
          ${d}
        </button>
      </div>
    `;
  }

  html += `</div>`;
  popup.innerHTML = html;
}

function openOrderDatePicker() {
  toggleOrderMiniCalendar();
}

function setOrderCurrency(curr) {
  currentOrderCurrency = curr || 'KHR';
  const btnKhr = document.getElementById('curr-btn-khr');
  const btnThb = document.getElementById('curr-btn-thb');
  const btnUsd = document.getElementById('curr-btn-usd');

  const activeCls = 'w-8 h-8 rounded-lg font-mono font-bold text-xs flex items-center justify-center active:scale-90 transition shadow-sm bg-orange-500 text-white';
  const inactiveCls = 'w-8 h-8 rounded-lg font-mono font-bold text-xs flex items-center justify-center active:scale-90 transition shadow-sm bg-white/10 hover:bg-white/20 border border-white/20 text-slate-300';

  if (btnKhr) btnKhr.className = (currentOrderCurrency === 'KHR' ? activeCls : inactiveCls);
  if (btnThb) btnThb.className = (currentOrderCurrency === 'THB' ? activeCls : inactiveCls);
  if (btnUsd) btnUsd.className = (currentOrderCurrency === 'USD' ? activeCls : inactiveCls);

  onPriceRawInput(false);
}

function onPriceRawInput(isTyping = false) {
  const priceRawInput = document.getElementById('order-field-price-raw');
  const totalUsdInput = document.getElementById('order-field-total-usd');
  const raw = cleanNumber(priceRawInput?.value);

  if (!raw || raw <= 0) {
    if (totalUsdInput) totalUsdInput.value = '';
    calculateOrderFinancials();
    return;
  }

  // ពេលវាយបញ្ចូល បើទឹកប្រាក់ធំជាង ឬស្មើ 10,000 កំណត់ស្វ័យប្រវត្តិជាប្រាក់រៀល (KHR)
  if (isTyping && raw >= 10000 && currentOrderCurrency !== 'KHR') {
    setOrderCurrency('KHR');
    return;
  }

  let totalUsd = 0;
  if (currentOrderCurrency === 'KHR') {
    // 360,000៛ / 4000 = $90.00
    totalUsd = raw / 4000;
  } else if (currentOrderCurrency === 'THB') {
    // រូបមន្តពិតតាម Google Sheet Col N: (M * 0.97) / 35.6
    totalUsd = (raw * 0.97) / 35.6;
  } else if (currentOrderCurrency === 'USD') {
    totalUsd = raw;
  }

  if (totalUsdInput) {
    totalUsdInput.value = totalUsd.toFixed(2);
  }
  calculateOrderFinancials();
}

