function openEditBudgetModal() {
  const current = parseFloat(localStorage.getItem('sd_monthly_budget')) || 450;
  const input = prompt('🎯 កំណត់គោលដៅចំណាយប្រចាំខែ ($):', current);
  if (input !== null && input.trim() !== '') {
    const val = parseFloat(input.trim());
    if (!isNaN(val) && val >= 0) {
      localStorage.setItem('sd_monthly_budget', val);
      if (typeof showToastNotification === 'function') {
        showToastNotification(`🎯 បានកំណត់គោលដៅចំណាយ $${val}/ខែ រួចរាល់!`);
      }
      if (typeof renderCurrentView === 'function') renderCurrentView();
    }
  }
}
window.openEditBudgetModal = openEditBudgetModal;

function toggleAnalyticsProfitMode() {
  appState.analyticsProfitMode = (appState.analyticsProfitMode === 'net') ? 'gross' : 'net';
  if (typeof renderCurrentView === 'function') renderCurrentView();
}
window.toggleAnalyticsProfitMode = toggleAnalyticsProfitMode;

function selectAnalyticsExpenseCategory(catName) {
  const decoded = decodeURIComponent(catName);
  if (appState.analyticsExpenseCategoryFilter === decoded) {
    appState.analyticsExpenseCategoryFilter = 'all';
  } else {
    appState.analyticsExpenseCategoryFilter = decoded;
  }
  if (navigator.vibrate) try { navigator.vibrate(15); } catch (_) {}
  if (typeof renderCurrentView === 'function') renderCurrentView();
}
window.selectAnalyticsExpenseCategory = selectAnalyticsExpenseCategory;

function toggleAnalyticsExpenseChartMode() {
  appState.analyticsExpenseChartMode = (appState.analyticsExpenseChartMode === 'donut') ? 'trend' : 'donut';
  if (navigator.vibrate) try { navigator.vibrate(12); } catch (_) {}
  if (typeof renderCurrentView === 'function') renderCurrentView();
}
window.toggleAnalyticsExpenseChartMode = toggleAnalyticsExpenseChartMode;

function setAnalyticsExpenseChartMode(mode) {
  if (appState.analyticsExpenseChartMode !== mode) {
    appState.analyticsExpenseChartMode = mode;
    if (navigator.vibrate) try { navigator.vibrate(12); } catch (_) {}
    if (typeof renderCurrentView === 'function') renderCurrentView();
  }
}
